quests[9244] = { id = 9244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisschuppenarmschienen", description = "Dank Euch und Omarion, möge er in Frieden ruhen, bin ich nun im Stande, Eisschuppenarmschienen herzustellen. Ihr müsst mir lediglich die Materialien dafür bringen und eine geringe Handwerksgebühr zahlen.", sourceObjective = "Handwerker Wilhelm bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte 4 gefrorene Runen, 16 schwere Skorpidschuppen, 5 Essenzen des Wassers, 3 geschmeidige unverwüstliche Bälge und 200 Gold.", sourceObjectiveStatus = "unverified-source-field" }
quests[9245] = { id = 9245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisschuppenstulpen", description = "Dank Euch und Omarion (Möge er in Frieden ruhen), bin ich nun im Stande, Eisschuppenstulpen herzustellen. Ihr müsst mir lediglich die Materialien dafür bringen und eine geringe Handwerksgebühr zahlen.", sourceObjective = "Handwerker Wilhelm bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte 5 gefrorene Runen, 16 schwere Skorpidschuppen, 5 Essenzen des Wassers, 3 geschmeidige unverwüstliche Bälge und 200 Gold.", sourceObjectiveStatus = "unverified-source-field" }
quests[9246] = { id = 9246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisschuppenbrustplatte", description = "Dank Euch und Omarion (Möge er in Frieden ruhen), bin ich nun im Stande, eine Eisschuppenbrustplatte herzustellen. Ihr müsst mir lediglich die Materialien dafür bringen und eine geringe Handwerksgebühr zahlen.", sourceObjective = "Handwerker Wilhelm bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte 8 gefrorene Runen, 24 schwere Skorpidschuppen, 7 Essenzen des Wassers, 5 geschmeidige unverwüstliche Bälge und 300 Gold. Euer Ruf bei der Argentumdämmerung muss außerdem ehrfürchtig sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[9247] = { id = 9247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf des Bewahrers", description = "{name},\n\nIn der Vergangenheit habt Ihr die Interessen der Argentumdämmerung nach bestem Gewissen und Können gewahrt. In einer Zeit der größten Not, ertönt wieder einmal der Ruf zu den Waffen.\n\n{name}, solltet Ihr uns unterstützen wollen, meldet Euch bitte bei dem Bewahrer der Schriften an der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", sourceObjective = "Bringt den Brief vom Bewahrer der Schriften zu ihm, in die Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Ah, {name}, es ist schön Euch zu sehen.", completion = "Schon dadurch, dass Ihr unseren Ruf beantwortet habt, stehen wir in Eurer Schuld, {name}. Die Argentumdämmerung ist sich sicher, dass Euer leuchtendes Beispiel auch den anderen Kämpfern gezeigt hat, wie man die Geißel zurückwirft!", sourceObjectiveStatus = "unverified-source-field" }
quests[9248] = { id = 9248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine bescheidene Darbringung", description = "Ishnu-alah, {race}. Bringt mir den Beweis für den Tod eines Lords des abyssischen Rates und ich werde Euch mit einem Gegenstand entlohnen, der Euch bei Euren Kämpfen gegen die Qiraji von großem Nutzen sein wird.", sourceObjective = "Aurel Goldleaf auf Burg Cenarius in Silithus möchte, dass Ihr ihr 1 abyssisches Szepter bringt. Euer Ruf bei dem Zirkel des Cenarius muss außerdem wohlwollend sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[9249] = { id = 9249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "40 Lose - Bauplan: Dampfpanzersteuerung" }
quests[9250] = { id = 9250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grundstab von Atiesh", description = "Mit dem Grundstab ist bereits der wichtigste Teil von Atiesh vervollständigt worden. Es fehlen lediglich noch Stabkopf und -fuß. Außerdem gibt es noch ein kleineres Problem bezüglich des Stabs und seiner Rolle hinsichtlich Sargeras' Lenkung zum Bösen.\n\nFindet jemanden, der Euch beim Aufspüren der noch fehlenden Teile und beim Austreiben alles Verderbten aus dem Hohestab zur Seite steht.", sourceObjective = "Findet jemanden, der Euch dabei hilft, die letzten beiden Teile des Stabs zu finden und das Böse daraus zu vertreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9251] = { id = 9251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atiesh, der korrumpierte Hohestab", description = "Ihr fragt Euch, warum Ihr noch immer am Leben seid? Schließlich haltet Ihr einen Gegenstand in Euren Händen, der vom Bösen erfüllt ist. Die Antwort ist nicht eindeutig, {name}. Ich tue nur, was ich tun muss.\n\nKel'Thuzad sitzt auf seinem Thron hoch oben in Naxxramas, konspiriert... Er sucht was Ihr besitzt und besitzt was Ihr sucht.\n\nWas den Stabfuß angeht, er wurde von dem Zwerg, Brann Bronzebeard, gehalten, als er Ahn'Qiraj betrat. Er hat Ahn'Qiraj zwar verlassen, den Stabfuß von Atiesh jedoch zurückgelassen.\n\nSolltet Ihr beim Wiedererlangen der Stücke Erfolg haben, kehrt mit ihnen zu mir zurück.", sourceObjective = "Anachronos in den Höhlen der Zeit in Tanaris möchte den Stabkopf und -fuß von Atiesh.", sourceObjectiveStatus = "unverified-source-field" }
quests[9257] = { id = 9257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atiesh, Hohestab des Wächters", description = "Die letzte Aufgabe ist zugleich die schwierigste von allen, {name}. Ihr seid einem alten Gott und dem General des Lichkönigs gegenübergetreten und habt beide besiegt. Nun müsst Ihr Euch jedoch der Hand Sargeras' stellen.\n\nBringt den Stab nach Stratholme. Es ist der Ort, an dem Ihr geheiligten Boden finden werdet: Boden, auf dem die mächtigsten Ritter Lordaerons getötet wurden. Platziert den korrumpierten Stab auf dem heiligen Grund und bereitet Euch darauf vor, dass eine Welle immenser Macht daraus hervorbrechen wird... Vernichtet das dämonische Wesen, das den Stab kontrolliert and kehrt zu mir zurück.", sourceObjective = "Anachronos in den Höhlen der Zeit in Tanaris möchte, dass Ihr Atiesh, den Hohestab des Wächters, nach Stratholme bringt und dort auf dem geheiligten Boden platziert. Bezwingt das Wesen, das aus dem Stab getrieben wurde, und kehrt danach wieder zu ihm zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9259] = { id = 9259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verrat am Blutsegel" }
quests[9260] = { id = 9260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erforscht die Geißel von Stormwind", description = "Die Geißel hat genau vor unserer Nase Stellung genommen; wir können das nicht weiter untätig hinnehmen! Ihr steht uns doch sicherlich bei der Verteidigung von Stormwind gegen diese verfluchten Eindringlinge zur Seite?\n\nEs gibt dort draußen ein paar merkwürdige Runenkreise, deren Energie genauso leuchtet wie die, die die Untoten und die Nekropole dort oben umgibt. Ich bin mir sicher, dass sie von Bedeutung sind. Findet heraus, was es damit auf sich hat. Merzt diese entarteten Kreaturen aus, wenn Ihr schon mal dabei seid. Ich erwarte Euch mit Beweisen für Eure Taten und Neuigkeiten von Euren Erkundungen zurück. Ihr werdet nicht leer ausgehen. Zieht jetzt los!", sourceObjective = "Beschafft Euch drei dunkle nekrotische Steine von der Geißel vor den Toren Stormwinds. Stellt außerdem Nachforschungen über die glühenden Runenkreise in der Nähe ihres Lagers an.", progress = "Habt Ihr bereits Nachforschungen angestellt? Uns bleibt keine Zeit zum Trödeln!", completion = "Hmm. Was Eure Nachforschungen betrifft, so scheinen diese Stimmen in den Kreisen... sie scheinen einer Art Kommunikation zu dienen. Mich schaudert es bei dem Gedanken, welch abartige Geister mit Hilfe dieser Magie angerufen werden. Nun ja, Ihr scheint ja in einem Stück davongekommen zu sein. Die Argentumdämmerung schätzt Eure Bemühungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9261] = { id = 9261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erforscht die Geißel von Ironforge", description = "Die Geißel hat genau vor unserer Nase Stellung genommen; wir können das nicht weiter untätig hinnehmen! Ihr steht uns doch sicherlich bei der Verteidigung von Ironforge gegen diese verfluchten Eindringlinge zur Seite?\n\nEs gibt dort draußen ein paar merkwürdige Runenkreise, deren Energie genauso leuchtet wie die, die die Untoten und die Nekropole dort oben umgibt. Ich bin mir sicher, dass sie von Bedeutung sind. Findet heraus, was es damit auf sich hat. Merzt diese entarteten Kreaturen aus, wenn Ihr schon mal dabei seid. Ich erwarte Euch mit Beweisen für Eure Taten und Neuigkeiten von Euren Erkundungen zurück. Ihr werdet nicht leer ausgehen. Zieht jetzt los!", sourceObjective = "Beschafft Euch drei dunkle nekrotische Steine von der Geißel vor den Toren von Ironforge. Stellt außerdem Nachforschungen über die glühenden Runenkreise in der Nähe ihres Lagers an.", progress = "Habt Ihr bereits Nachforschungen angestellt? Uns bleibt keine Zeit zum Trödeln!", completion = "Hmm. Was Eure Nachforschungen betrifft, so scheinen diese Stimmen in den Kreisen... sie scheinen einer Art Kommunikation zu dienen. Mich schaudert es bei dem Gedanken, welch abartige Geister mit Hilfe dieser Magie angerufen werden. Nun ja, Ihr scheint ja in einem Stück davongekommen zu sein. Die Argentumdämmerung schätzt Eure Bemühungen.", sourceObjectiveStatus = "unverified-source-field" }
