quests[9273] = { id = 9273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Redeem iCoke Prize Voucher" }
quests[9292] = { id = 9292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesprungener nekrotischer Kristall", description = "Ihr entdeckt beim Körper der toten Monstrosität einen gesprungenen Kristall, der langsam mit nekrotischer Energie pulsiert.", sourceObjective = "Bringt den gesprungenen nekrotischen Kristall zu Lieutenant Orrin außerhalb der Tore von Stormwind.", progress = "Ja, was gibt's?", completion = "Hm, Ihr habt das beim Körper einer der Monstrositäten gefunden?\n\nWir haben von Basislagern der Nekropole gehört, die die Geißel heraufbeschworen hat. Ich vermute, dass sie eines davon innerhalb von Stormwind errichten wollten. Es ist gut, dass sie damit erfolglos waren.", sourceObjectiveStatus = "unverified-source-field" }
quests[9295] = { id = 9295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brief von der Front", description = "Ihr habt dieses Schreiben bei einem der zahlreichen Diener der Geißel gefunden, die Ihr getötet habt. Sein Äußeres und der Geruch lassen darauf schließen, dass es sich schon seit längerem im Besitz des Untoten befunden haben muss. Vielleicht wäre ja jemand bei der Kapelle des hoffnungsvollen Lichts an einer weiteren Untersuchung interessiert...", sourceObjective = "Bringt den zerfledderten Brief zum Bewahrer der Schriften bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Ja? Was habt Ihr denn da?", completion = "Wie tragisch. Diese Zeilen, die eindeutig für jemanden bestimmt waren, den der Soldat liebte, haben ihren Empfänger nie erreicht. Die beschriebenen Geschehnisse haben sich vor Jahren ereignet; Ich weiß nicht, ob der bestimmte Empfänger noch lebt.\n\nMan kann jedoch noch hoffen. Anhand des angegebenen Namens und der enthaltenen Informationen, könnte ich die Familie vielleicht noch ausfindig machen! Es wird einiges an Nachforschungen bedürfen, aber der Bibliothekar in Stormwind ist mir noch einen Gefallen schuldig...\n\nDanke für diesen Dienst. Mit Eurer Hilfe findet womöglich noch jemand seinen verdienten Seelenfrieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9296] = { id = 9296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "reuse" }
