quests[9298] = { id = 9298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "reuse" }
quests[9299] = { id = 9299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Notiz von der Front", description = "Ihr habt dieses Schreiben bei einem der zahlreichen Diener der Geißel gefunden, die Ihr getötet habt. Sein Äußeres und der Geruch lassen darauf schließen, dass es sich schon seit längerem im Besitz des Untoten befunden haben muss. Vielleicht wäre ja jemand bei der Kapelle des hoffnungsvollen Lichts an einer weiteren Untersuchung interessiert...", sourceObjective = "Bringt die verblichene Notiz zum Bewahrer der Schriften bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Ja? Was habt Ihr denn da?", completion = "Wie tragisch. Diese Zeilen, die eindeutig für jemanden bestimmt waren, den der Soldat liebte, haben ihren Empfänger nie erreicht. Die beschriebenen Geschehnisse haben sich vor Jahren ereignet; Ich weiß nicht, ob der bestimmte Empfänger noch lebt.\n\nMan kann jedoch noch hoffen. Anhand des angegebenen Namens und der enthaltenen Informationen, könnte ich die Familie vielleicht noch ausfindig machen! Es wird einiges an Nachforschungen bedürfen, aber der Bibliothekar in Stormwind ist mir noch einen Gefallen schuldig...\n\nDanke für diesen Dienst. Mit Eurer Hilfe findet womöglich noch jemand seinen verdienten Seelenfrieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9300] = { id = 9300, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seite von der Front", description = "Ihr habt dieses Schreiben bei einem der zahlreichen Diener der Geißel gefunden, die Ihr getötet habt. Sein Äußeres und der Geruch lassen darauf schließen, dass es sich schon seit längerem im Besitz des Untoten befunden haben muss. Vielleicht wäre ja jemand bei der Kapelle des hoffnungsvollen Lichts an einer weiteren Untersuchung interessiert...", sourceObjective = "Bringt die zerfranste Seite zum Bewahrer der Schriften bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Ja? Was habt Ihr denn da?", completion = "Wie tragisch. Diese Zeilen, die eindeutig für jemanden bestimmt waren, den der Soldat liebte, haben ihren Empfänger nie erreicht. Die beschriebenen Geschehnisse haben sich vor Jahren ereignet; Ich weiß nicht, ob der bestimmte Empfänger noch lebt.\n\nMan kann jedoch noch hoffen. Anhand des angegebenen Namens und der enthaltenen Informationen, könnte ich die Familie vielleicht noch ausfindig machen! Es wird einiges an Nachforschungen bedürfen, aber der Bibliothekar in Stormwind ist mir noch einen Gefallen schuldig...\n\nDanke für diesen Dienst. Mit Eurer Hilfe findet womöglich noch jemand seinen verdienten Seelenfrieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9301] = { id = 9301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umschlag von der Front", description = "Ihr habt dieses Schreiben bei einem der zahlreichen Diener der Geißel gefunden, die Ihr getötet habt. Sein Äußeres und der Geruch lassen darauf schließen, dass es sich schon seit längerem im Besitz des Untoten befunden haben muss. Vielleicht wäre ja jemand bei der Kapelle des hoffnungsvollen Lichts an einer weiteren Untersuchung interessiert...", sourceObjective = "Bringt den blutbefleckten Umschlag zum Bewahrer der Schriften bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Ja? Was habt Ihr denn da?", completion = "Wie tragisch. Diese Zeilen, die eindeutig für jemanden bestimmt waren, den der Soldat liebte, haben ihren Empfänger nie erreicht. Die beschriebenen Geschehnisse haben sich vor Jahren ereignet; Ich weiß nicht, ob der bestimmte Empfänger noch lebt.\n\nMan kann jedoch noch hoffen. Anhand des angegebenen Namens und der enthaltenen Informationen, könnte ich die Familie vielleicht noch ausfindig machen! Es wird einiges an Nachforschungen bedürfen, aber der Bibliothekar in Stormwind ist mir noch einen Gefallen schuldig...\n\nDanke für diesen Dienst. Mit Eurer Hilfe findet womöglich noch jemand seinen verdienten Seelenfrieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9302] = { id = 9302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schreiben von der Front", description = "Ihr habt dieses Schreiben bei einem der zahlreichen Diener der Geißel gefunden, die Ihr getötet habt. Sein Äußeres und der Geruch lassen darauf schließen, dass es sich schon seit längerem im Besitz des Untoten befunden haben muss. Vielleicht wäre ja jemand bei der Kapelle des hoffnungsvollen Lichts an einer weiteren Untersuchung interessiert...", sourceObjective = "Bringt das zerknitterte Schreiben zum Bewahrer der Schriften bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Ja? Was habt Ihr denn da?", completion = "Wie tragisch. Diese Zeilen, die eindeutig für jemanden bestimmt waren, den der Soldat liebte, haben ihren Empfänger nie erreicht. Die beschriebenen Geschehnisse haben sich vor Jahren ereignet; Ich weiß nicht, ob der bestimmte Empfänger noch lebt.\n\nMan kann jedoch noch hoffen. Anhand des angegebenen Namens und der enthaltenen Informationen, könnte ich die Familie vielleicht noch ausfindig machen! Es wird einiges an Nachforschungen bedürfen, aber der Bibliothekar in Stormwind ist mir noch einen Gefallen schuldig...\n\nDanke für diesen Dienst. Mit Eurer Hilfe findet womöglich noch jemand seinen verdienten Seelenfrieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9304] = { id = 9304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dokument von der Front", description = "Ihr habt dieses Schreiben bei einem der zahlreichen Diener der Geißel gefunden, die Ihr getötet habt. Sein Äußeres und der Geruch lassen darauf schließen, dass es sich schon seit längerem im Besitz des Untoten befunden haben muss. Vielleicht wäre ja jemand bei der Kapelle des hoffnungsvollen Lichts an einer weiteren Untersuchung interessiert...", sourceObjective = "Bringt das verschmierte Dokument zum Bewahrer der Schriften bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Ja? Was habt Ihr denn da?", completion = "Wie tragisch. Diese Zeilen, die eindeutig für jemanden bestimmt waren, den der Soldat liebte, haben ihren Empfänger nie erreicht. Die beschriebenen Geschehnisse haben sich vor Jahren ereignet; Ich weiß nicht, ob der bestimmte Empfänger noch lebt.\n\nMan kann jedoch noch hoffen. Anhand des angegebenen Namens und der enthaltenen Informationen, könnte ich die Familie vielleicht noch ausfindig machen! Es wird einiges an Nachforschungen bedürfen, aber der Bibliothekar in Stormwind ist mir noch einen Gefallen schuldig...\n\nDanke für diesen Dienst. Mit Eurer Hilfe findet womöglich noch jemand seinen verdienten Seelenfrieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9310] = { id = 9310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwacher nekrotischer Kristall", description = "Ihr findet beim Körper der toten Kreatur einen Kristall, der schwache nekrotische Energie ausstrahlt.", sourceObjective = "Bringt den schwachen nekrotischen Kristall zu Lieutenant Rukag im Hof von Undercity.", progress = "Kann ich Euch irgendwie weiterhelfen?", completion = "Ihr sagt, dass Ihr das bei einer der Kreaturen gefunden habt, die die Stadt angreifen?\n\nWir haben von Basislagern der Nekropole gehört, die die Geißel heraufbeschworen hat. Ich vermute, dass sie eines davon innerhalb von Undercity errichten wollten. Wir müssen zukünftig sehr vorsichtig sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[9317] = { id = 9317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geweihte Wetzsteine", progress = "Wenn Ihr mir acht nekrotische Runen von den Geißelinvasoren besorgt, kann ich Euch einen geweihten Wetzstein dafür geben. Er sollte Euch im Kampf gegen die Diener des Lichkönigs eine große Hilfe sein.", completion = "Danke, {name}. Hier ist Euer geweihter Wetzstein. Verwendet ihn weise." }
quests[9318] = { id = 9318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesegnetes Zauberöl", progress = "Die Argentumdämmerung wird Euch im Tausch gegen die nekrotischen Runen der Geißelinvasoren eine Phiole gesegnetes Zauberöl geben.", completion = "Ich hoffe, dass Ihr in Euren zukünftigen Schlachten davon Gebrauch machen könnt." }
quests[9319] = { id = 9319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Licht im Dunkeln", description = "Wir sind nicht die Einzigen, die dieses Fest feiern, {name}. Die Flamme ist ein wichtiger Bestandteil aller Lebewesen, aller Kulturen. Selbst an den dunkelsten Orten beginnen die Feuer zu leuchten.\n\nWenn Ihr dergleichen sehen möchtet, so wagt Euch in die Tiefe. Sucht nach den Freudenfeuern in Stratholme, Scholomance, bei den Ogern des Düsterbruchs und in den Hallen der Blackrockspitze selbst. Ich erwarte Eure Rückkehr.", sourceObjective = "Findet und berührt die Freudenfeuer innerhalb der Blackrockspitze, dem Düsterbruch, Scholomance und Stratholme. Kehrt dann zum Flammenbewahrer zurück.", progress = "Habt Ihr Euch im Dunkeln zurechtgefunden?", completion = "Euer Wesen erstrahlt mit der Energie der Flammen, die Ihr gefunden habt, {name}. Das Feuer, mit dem Ihr in Berührung gekommen seid,  ist mächtig. Mit dem richtigen Wissen, kann man sich diese Macht zu Nutzen machen...\n\n\n\nAh! Soweit so gut. Ich hoffe dies wird Euren Weg erleuchten, wohin immer Ihr auch gehen mögt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9320] = { id = 9320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erheblicher Manatrank", progress = "Neben unseren anderen Vorräten verfügen wir auch über eine gewisse Zahl an erheblichen Manatränken, die für Euch von Nutzen sein könnten. Ich werde Euch einen im Tausch gegen fünfzehn nekrotische Runen geben.", completion = "Bitte sehr, {name}. Seid vorsichtig da draußen. Wir sind zu wenige, als dass wir uns viele Verluste auf dem Schlachtfeld leisten könnten." }
quests[9321] = { id = 9321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erheblicher Heiltrank" }
quests[9322] = { id = 9322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glühende Feuer in Kalimdor", description = "Die Freudenfeuer des Sonnenwendfests werden überall in Azeroth gefeiert, die mannigfaltigen Länder Kalimdors sind dabei keine Ausnahme. Ihr scheint mir tauglich für eine Reise -- wie wäre es mit einem Ausflug?\n\nDas Sonnenwendfest ist erst dann ein Ereignis, wenn man die blau glühenden Feuer in der Welt gesehen hat. Die Feiernden haben Feuer im eisigen Westen von Winterspring, im Nordosten von Azshara, in der Nähe der Heldenwacht in Silithus und beim Eingang zum üppigen Un'Goro-Krater entzündet. Kehrt zu mir zurück, sobald Ihr die Reise beendet habt.", sourceObjective = "Sucht die Lager des Sonnenwendfests in Azshara, Silithus, dem Un'Goro-Krater und Winterspring auf. Kehrt dann zum Flammenbewahrer zurück.", completion = "Euer Geist erstrahlt mit der Wärme der Feuer Kalimdors. Ist die Hitze nicht anregend?\n\nWenn die Macht von Euch schwindet, könnte Euch dies hier vielleicht dabei helfen, das Ganze wieder aufleben zu lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9323] = { id = 9323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glühende Feuer in den östlichen Königreichen", description = "Das Fest der Flamme ist im ganzen Land verbreitet, {class}. Kein Ort bleibt von der Wärme dieses Ereignisses unberührt, und die prächtigsten Feuer lodern in einem strahlenden Blau. Sucht nach ihnen.\n\nEines befindet sich genau nördlich von der Blackrockspitze. Die anderen liegen tief im Innern der östlichen Pestländer, in der Nähe eines verfallenen Dorfes; entlang der Straße, die zu den Klippen im bergigen Hinterland führt, und auf dem Weg zu dem Dunklen Portal in den verwüsteten Landen.\n\nKehrt anschließend zu mir zurück.", sourceObjective = "Reist zu den Lagern des Sonnenwendfests in den verwüsteten Landen, den östlichen Pestländern, dem Hinterland und der sengenden Schlucht. Kehrt dann zum Flammenbewahrer zurück.", completion = "Ah, da seid Ihr also. Etwas erschöpfter, ein wenig schmutziger, aber erleuchtet! Die Wärme berührt und vereint uns alle während dieser Zeit. Euer Wesen erstrahlt mit der Macht der Feuer, die Ihr berührt habt.\n\nAh, ich vermute, dass Erleuchtung heutzutage wohl eher als eine armselige Belohnung für eine Aufgabe wie diese angesehen wird. Nehmt dies hier, bitte, und genießt das Fest.", sourceObjectiveStatus = "unverified-source-field" }
quests[9324] = { id = 9324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raubt die Flamme von Orgrimmar", description = "Die Flamme, die aus dem Zentrum von Orgrimmar entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Meister der Lehren könnte vielleicht mehr darüber wissen...", sourceObjective = "Bringt die Flamme von Orgrimmar zu dem Meister der Lehren.", progress = "Ihr glüht ja förmlich, {race}. Was habt Ihr da?", completion = "Was ist das? Sollte ich mich nicht täuschen, so wurde diese Flamme aus dem Herzen Orgrimmars entwendet! Die sengende Hitze spiegelt die kämpferischen Herzen der Orcs und Trolle wider. Was für ein Gewinn für unsere Sammlung! Wie mutig Ihr doch seid - sich in den Bau des Feindes einzuschleichen, um die heilige Flamme zu erlangen!\n\nIch frage mich, welch' Mächte sich in den anderen Städten versteckt halten...", sourceObjectiveStatus = "unverified-source-field" }
quests[9325] = { id = 9325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raubt die Flamme von Thunder Bluff", description = "Die Flamme, die dem Schamanen von Thunder Bluff entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Meister der Lehren könnte vielleicht mehr darüber wissen...", sourceObjective = "Bringt die Flamme von Thunder Bluff zu dem Meister der Lehren.", progress = "Ihr glüht ja förmlich, {race}. Was habt Ihr da?", completion = "Sollte mich meine Vermutung nicht täuschen, so wurde diese Flamme aus Thunder Bluff entwendet! Die Macht der Geister ist deutlich hörbar! Ihr seid ganz schön gerissen, {name}. Nehmt dies als gerechte Anerkennung Eures Könnens. Hm, hätten wir doch auch all die Flammen von den anderen Städten...", sourceObjectiveStatus = "unverified-source-field" }
quests[9326] = { id = 9326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raubt die Flamme von Undercity", description = "Die Flamme, die aus den Ruinen über Undercity entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Meister der Lehren könnte vielleicht mehr darüber wissen...", sourceObjective = "Bringt die Flamme von Undercity zu dem Meister der Lehren.", progress = "Ihr glüht ja förmlich, {race}. Was habt Ihr da?", completion = "Hm... was für ein seltsames Feuer! Es flackert schwach, ist fast nur noch ein Glühen, aber die Hitze ist stark. Ihr sagt, dass Ihr es aus Undercity entwendet habt? Faszinierend. Wer weiß, was wir mit den Flammen aller drei Städte erreichen könnten?", sourceObjectiveStatus = "unverified-source-field" }
quests[9330] = { id = 9330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raubt die Flamme von Stormwind", description = "Die Flamme, die aus dem Zentrum von Stormwind entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Geschichtenerzähler könnte vielleicht mehr darüber wissen...", sourceObjective = "Bringt die Flamme von Stormwind zu dem Geschichtenerzähler.", progress = "Ihr glüht ja förmlich, {race}. Was habt Ihr da?", completion = "Also dieses hell leuchtende Feuer... Ihr sagt es kommt aus Stormwind? Bemerkenswert! Das muss ein ziemliches Abenteuer gewesen sein! Ich werde Euch dafür natürlich entlohnen. Solltet Ihr etwas Ähnliches finden, kommt bitte sofort zu mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[9331] = { id = 9331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raubt die Flamme von Ironforge", description = "Die Flamme, die aus dem Zentrum von Ironforge entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Geschichtenerzähler könnte vielleicht mehr darüber wissen...", sourceObjective = "Bringt die Flamme von Ironforge zu dem Geschichtenerzähler.", progress = "Ihr glüht ja förmlich, {race}. Was habt Ihr da?", completion = "Diese kraftvolle Flamme muss aus den Hallen von Ironforge stammen; sie ist so unerschütterlich wie die Zwege selbst. Gute Beute, {name}. Hätte ich nur die Flammen der anderen Städte... naja, macht Euch nichts draus. Hier ist Euer Lohn.", sourceObjectiveStatus = "unverified-source-field" }
quests[9332] = { id = 9332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raubt die Flamme von Darnassus", description = "Die Flamme, die von der Küste Teldrassils entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber der Geschichtenerzähler könnte vielleicht mehr darüber wissen...", sourceObjective = "Bringt die Flamme von Darnassus zu dem Geschichtenerzähler.", progress = "Ihr glüht ja förmlich, {race}. Was habt Ihr da?", completion = "Dieses Feuer ist mit uraltem Kummer erfüllt, {name}. Ihr habt es aus dem Herzen Teldrassils, ja? Unglaublich! Hier, als Anerkennung für Euer Können. Kehrt zu mir zurück, falls Ihr etwas Ähnliches finden solltet - ich könnte Verwendung dafür haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[9333] = { id = 9333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handschuhe der Argentumdämmerung", progress = "Bringt Ihr mir dreißig nekrotische Runen, gebe ich Euch im Gegenzug einen Handschutz Eurer Wahl dafür. Dieser sollte sich in Eurem Kampf gegen die untote Geißel als sehr nützlich erweisen.", completion = "Ihr habt gute Arbeit geleistet, {name}. Nehmt den von Euch gewählten Handschutz als Dank für Eure Mühen." }
quests[9334] = { id = 9334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesegnetes Zauberöl", progress = "Die Argentumdämmerung wird Euch im Tausch gegen die nekrotischen Runen der Geißelinvasoren eine Phiole gesegnetes Zauberöl geben.", completion = "Ich hoffe, dass Ihr in Euren zukünftigen Schlachten davon Gebrauch machen könnt." }
quests[9335] = { id = 9335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geweihte Wetzsteine", progress = "Wenn Ihr mir acht nekrotische Runen von den Geißelinvasoren besorgt, kann ich Euch einen geweihten Wetzstein dafür geben. Er sollte Euch im Kampf gegen die Diener des Lichkönigs eine große Hilfe sein.", completion = "Danke, {name}. Hier ist Euer geweihter Wetzstein. Verwendet ihn weise." }
quests[9336] = { id = 9336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erheblicher Heiltrank" }
quests[9337] = { id = 9337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erheblicher Manatrank", progress = "Neben unseren anderen Vorräten verfügen wir auch über eine gewisse Zahl an erheblichen Manatränken, die für Euch von Nutzen sein könnten. Ich werde Euch einen im Tausch gegen fünfzehn nekrotische Runen geben.", completion = "Bitte sehr, {name}. Seid vorsichtig da draußen. Wir sind zu wenige, als dass wir uns viele Verluste auf dem Schlachtfeld leisten könnten." }
quests[9338] = { id = 9338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treue zum Zirkel des Cenarius", progress = "Selbst wenn Ihr keinen Bedarf an unseren materiellen Belohungen habt, sind diese Abzeichen ein Symbol für gegenseitiges Vertrauen und Freundschaft.\n\nBringt sie mir. Außerordentliche Dienste von Euch werde ich sorgsam vermerken.", completion = "Ihr ehrt uns, {name}. Eure fortgesetzten Anstrengungen helfen uns, alle Hindernisse zu überwinden." }
quests[9339] = { id = 9339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Lohn des Diebes", description = "Die Flamme, die aus dem unmittelbaren Zentrum von Stormwind entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber (NAME) könnte vielleicht mehr darüber wissen...", sourceObjective = "Bringt die Flamme von Stormwind zu (NAME).", completion = "Ihr habt Euch heute bewiesen, {name}.\n\nIch habe zwar nicht viel, das ich Euch geben könnte, aber bitte nehmt diese Krone, eine passende Belohnung für einen Eroberer. Möge sie Euren Weg erleuchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[9341] = { id = 9341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wappenrock der Argentumdämmerung", progress = "Ihr habt unserer Sache sehr gedient, {name}. Wenn ihr wollt, kann ich Euch einen Wappenrock der Argentumdämmerung zur Verfügung stellen. Wir sind stolz, Euch zu unseren Verbündeten zu zählen.", completion = "Nehmt diesen Wappenrock und tragt ihn mit Stolz. Vielleicht regen Eure Taten auch andere dazu an, zu den Waffen zu greifen und an unserem Kampf gegen die Geißel teilzunehmen." }
quests[9343] = { id = 9343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wappenrock der Argentumdämmerung", progress = "Ihr habt unserer Sache sehr gedient, {name}. Wenn ihr wollt, kann ich Euch einen Wappenrock der Argentumdämmerung zur Verfügung stellen. Wir sind stolz, Euch zu unseren Verbündeten zu zählen.", completion = "Nehmt diesen Wappenrock und tragt ihn mit Stolz. Vielleicht regen Eure Taten auch andere dazu an, zu den Waffen zu greifen und an unserem Kampf gegen die Geißel teilzunehmen." }
quests[9353] = { id = 9353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Redeem iCoke Gift Box Voucher" }
quests[9362] = { id = 9362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsherr Krellian", description = "Die Zeit drängt, {name}! Meine Orakelsprüche haben eine machtvolle Quelle der Magie offenbart. Ich kann den Turm nicht verlassen und bitte Euch deshalb, diese bösartige Kreatur, die im Besitz dieses Artefakts ist, zu töten.\n\nDer erbärmliche Schwachkopf ist bekannt als Kriegsherr Krellian und versteckt sich hinter seinen Wachen im Tempel von Zin-Malor. Verbrennt ihn zu Asche und nehmt die prismatische Muschel, die er so begehrt, an Euch.", sourceObjective = "Beschafft die prismatische Muschel für Erzmagier Xylem. Der Erzmagier befindet sich in einem Turm auf den Klippen von Azshara.", progress = "Es ist keine Zeit zu verlieren! Habt Ihr die Muschel?", completion = "Mh, diese Muschel wird wahrlich von einer seltsamen Aura umgeben. Es scheint geradezu angebracht, dass Eure Belohnung für die Wiederbeschaffung zum Teil daraus besteht, diese magischen Fähigkeiten zu testen...", sourceObjectiveStatus = "unverified-source-field" }
quests[9364] = { id = 9364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gespaltene Magie", description = "Meine Untersuchungen haben den einzigartigen Zweck für die prismatische Muschel enthüllt.\n\nGreift die Grollflossen von Azshara mit Verwandlungszaubern an und tragt dabei diese Muschel bei Euch. Wenn Ihr einen Moment wartet, wird die chaotische Aura der Muschel dafür sorgen, dass sie sich für eine kurze Zeit in mehrere kleinere Versionen aufspalten. Tötet diese Kopien so schnell wie möglich, und deren gespaltene Essenzen werden in der Muschel gesammelt.\n\nKehrt zu mir zurück, sobald die Muschel gefüllt ist.", sourceObjective = "Verwandelt die Grollflossen von Azshara und tötet die Kopien, die einige Sekunden später auftauchen. Wenn Ihr 50 verwandelte Kopien vernichtet habt, kehrt zu Erzmagier Xylem in Azshara zurück.", progress = "Habt Ihr die Magie eingesammelt?", completion = "Wunderbar! Prächtig!\n\nNun sind wir in der Lage, diese Magie zu einem neuen Zauber zu formen. Seht!", sourceObjectiveStatus = "unverified-source-field" }
quests[9365] = { id = 9365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Lohn des Diebes", description = "Die Flamme, die aus dem unmittelbaren Zentrum von Stormwind entwendet wurde, durchflutet Euch mit Wärme. Diese durchdringende Macht ist Euch fremd, aber (NAME) könnte vielleicht mehr darüber wissen...", sourceObjective = "Bringt die Flamme von Stormwind zu (NAME).", sourceObjectiveStatus = "unverified-source-field" }
quests[9367] = { id = 9367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Fest des Feuers", description = "Die Zeit des Sonnenwendfests ist wieder angebrochen!\n\nJedes Jahr werden, wie die Tradition es verlangt, Flammenbewahrer auserkoren, die die Freudenfeuer in unseren Hauptstädten hüten. Auch wenn Feuer in ganz Azeroth brennen, so müssen unsere stets die heißesten und hellsten von allen sein, um dieser Zeit im Jahr ausreichend Ehrerbietung zu erweisen.\n\nIch hätte da übrigens eine Aufgabe für Euch. Mir ist noch nicht zu Ohren gekommen, ob die Feuer in allen Hauptstädten auch wirklich ordentlich brennen. Reist selbst dorthin und wärmt Euch im Schein der Flammen - überzeugt Euch, dass sie ausreichend heiß sind!", sourceObjective = "Wärmt Euch an den Freudenfeuern in Stormwind, Ironforge und Darnassus. Sprecht anschließend mit einem Meister der Lehren innerhalb der Hauptstädte.", completion = "Ausgezeichnet! Scheinbar haben wir dieses Jahr pflichtgetreue Flammenbewahrer ernannt, wenn die Freudenfeuer so herrlich brennen, wie Ihr es berichtet. Danke, dass Ihr der Sache für mich nachgegangen seid. Hier, nehmt dies als kleines Zeichen für meine Wertschätzung.", sourceObjectiveStatus = "unverified-source-field" }
quests[9368] = { id = 9368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Fest des Feuers", description = "Die Zeit des Sonnenwendfests ist wieder angebrochen!\n\nJedes Jahr werden, wie die Tradition es verlangt, Flammenbewahrer auserkoren, die die Freudenfeuer in unseren Hauptstädten hüten. Auch wenn Feuer in ganz Azeroth brennen, so müssen unsere stets die heißesten und hellsten von allen sein, um dieser Zeit im Jahr ausreichend Ehrerbietung zu erweisen.\n\nIch hätte da übrigens eine Aufgabe für Euch. Mir ist noch nicht zu Ohren gekommen, ob die Feuer in allen Hauptstädten auch wirklich ordentlich brennen. Reist selbst dorthin und wärmt Euch im Schein der Flammen - überzeugt Euch, dass sie ausreichend heiß sind!", sourceObjective = "Wärmt Euch an den Freudenfeuern in Orgrimmar, Thunder Bluff und Undercity. Sprecht anschließend mit einem Geschichtenerzähler innerhalb der Hauptstädte.", progress = "Brennen alle Feuer?", completion = "Ausgezeichnet! Scheinbar haben wir dieses Jahr pflichtgetreue Flammenbewahrer ernannt, wenn die Freudenfeuer so herrlich brennen, wie Ihr es berichtet. Danke, dass Ihr der Sache für mich nachgegangen seid. Hier, nehmt dies als kleines Zeichen für meine Wertschätzung.", sourceObjectiveStatus = "unverified-source-field" }
quests[9386] = { id = 9386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Licht im Dunkeln", description = "Ihr seid ziemlich eifrig, oder? Solltet Ihr Euch noch einmal in die Tiefen wagen, so bin ich gerne bereit, Euch dafür zu belohnen.\n\nSucht die Freudenfeuer in Stratholme, Scholomance, dem Düsterbruch und den Hallen der Blackrockspitze auf. Ich erwarte Eure Rückkehr, {name}.", sourceObjective = "Findet und berührt die Freudenfeuer innerhalb der Blackrockspitze, dem Düsterbruch, Scholomance und Stratholme. Sprecht dann mit dem Flammenbewahrer.", sourceObjectiveStatus = "unverified-source-field" }
quests[9388] = { id = 9388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lodernde Flammen in Kalimdor", description = "Heute lodern zahlreiche Flammen in der Welt, {name}. Die Feuer, die am schwierigsten zu unterhalten sind, leuchten grün; werden sie nicht ständig beaufsichtigt, brennen sie nicht lange. Versichert Euch für unseren Flammenbewahrer, dass die Smaragdfeuer in Kalimdor auch weiterhin lodern, eh?\n\nIhr findet sie in der Nähe von Ratchet im Brachland, unweit der Meistergleve in Dunkelküste, im Wald von Ashenvale bei der Brücke nahe des Außenpostens der Silverwing und entlang der Hauptstraße im Steinkrallengebirge, in der Nähe der Straße, die zur Scherwindklippe führt.", sourceObjective = "Sucht die Freudenfeuer in Ashenvale, dem Brachland, der Dunkelküste und dem Steinkrallengebirge auf. Sprecht anschließend mit dem Flammenbewahrer.", completion = "Ahhh, sie brennen also noch. Das freut mich; es wäre nicht gut, wenn die Feuer vorzeitig erlöschen würden. Ihr habt gute Arbeit geleistet, {name}. Nehmt dies mit meinem Segen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9389] = { id = 9389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lodernde Flammen in den östlichen Königreichen", description = "Die Feuer des Sonnenwendfests lassen das Land traditionsgemäß im Licht unzähliger Flammen erstrahlen. Manche behaupten, dass die grünen Flammen die besten seien, da sie so schwierig zu unterhalten sind und eine solch ungewöhnliche Farbgebung haben.\n\nVersichert Euch für unseren Flammenbewahrer, dass die Feuer in den östlichen Königreichen auch weiterhin lodern. Ihr findet sie in der Nähe von Dun Modr im Sumpfland, unweit von Pyrewood im Silberwald, bei den Klippen zum Leuchtturm in Westfall und nahe dem zerstörten Turm im Vorgebirge von Hillsbrad.", sourceObjective = "Sucht die Freudenfeuer im Vorgebirge von Hillsbrad, im Silberwald, in Westfall und dem Sumpfland auf. Sprecht anschließend mit dem Flammenbewahrer.", completion = "Ihr seid also wieder da und habt die Smaragdflammen dieser Welt gesehen. Was sagt Ihr, mh? Ein mit Sicherheit seltener und wunderschöner Anblick. Natürlich weiß ich, dass eine handfeste Belohnung mehr Anklang findet... also bitte, nehmt dies für Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9415] = { id = 9415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung bei Marschall Bluewall", description = "Gehört Ihr zu Marschall Bluewalls neuen Rekruten? Natürlich.\n\nAuf was wartet Ihr noch? Gute Soldaten verlieren ihr Leben in der Wüste. Freut es Euch nicht, bald dazuzugehören?\n\nLos jetzt, macht Euch auf den Weg... und trocknet dabei nicht aus.", sourceObjective = "Sprecht mit Marschall Bluewall beim Lager der Allianz in der Nähe des Zoraschwarmbaus.", completion = "Die Allianz braucht jeden tauglichen Rekrut, den sie bekommen kann. Die Horde hat ständig Verstärkung vom nördlichen Kontinent bekommen, wir mussten kämpfen, um überhaupt standzuhalten.\n\nLasst Euch die Lage von mir schildern.", sourceObjectiveStatus = "unverified-source-field" }
quests[9416] = { id = 9416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung bei General Kirika", description = "Ihr müsst zu General Kirikas neuen Rekruten gehören. Es wurde Zeit, dass Ihr kommt. Der Truppenverschleiß in der Wüste ist hoch.\n\nDie Zwerge haben tagtäglich Verstärkung bekommen, wir können es uns nicht leisten in unserem Kampf um Ressourcen in Silithus an Boden zu verlieren.\n\nLasst Euch vom General weitere Anweisungen geben. Ich muss Euch Rekruten lediglich finden, nicht ausbilden.", sourceObjective = "Sprecht mit General Kirika beim Lager der Horde in der Nähe des Regalschwarmbaus.", completion = "Es ist gut, dass Ihr hier seid, aber wir haben keine Zeit für überflüssige Worte. Was Ihr braucht, sind Anweisungen, und dann müsst Ihr losziehen.\n\nHört gut zu.", sourceObjectiveStatus = "unverified-source-field" }
quests[9419] = { id = 9419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchkämmen der Wüste", description = "Wir hatten vor kurzem herausgefunden, dass die Horde die Wüste von Silithus nach Ressourcen abgesucht hat, schenkten dem Ganzen aber keine besondere Beachtung. Wir dachten, es wäre die Sache nicht wert, eine größere Anzahl von Soldaten in dieser Bruthitze zu stationieren.\n\nWie dem auch sei, wir haben die Wichtigkeit dieser Ressourcen erkannt und versuchen nun, um jeden Preis aufzuholen.\n\nWenn Ihr uns unterstützen wollt, müsst Ihr in die Wüste gehen, dort nach Silithyst suchen und diesen anschließend hierher bringen.", sourceObjective = "Findet Silithyst, bringt es zum Silithystextraktor und sprecht anschließend mit Marschall Bluewall beim Lager der Allianz in der Nähe des Zoraschwarmbaus.", completion = "Dem Licht sei Dank, Eure Suche war erfolgreich.\n\nHätten wir nur eher damit begonnen, dann wären wir jetzt nicht in einer so verzweifelten Notlage. Wir müssen verhindern, dass die Schätze der Wüste in die Hände der Horde fallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9422] = { id = 9422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchkämmen der Wüste", description = "Wir haben die Wüste von Silithus bereits seit einiger Zeit nach Kristallressourcen durchkämmt. Die einzigen Gefahren, die sich uns dabei in den Weg gestellt haben, waren die Kreaturen, die dort heimisch sind, sowie Sand, Staub und Hitze.\n\nDie Allianz scheint nun aber Wind von unserem Unterfangen bekommen zu haben. Ein Rennen hat begonnen. Ein Rennen um die natürlichen Ressourcen und um deren Verteidigung.\n\nWir brauchen jede helfende Hand, die wir bekommen können. Ich hoffe Ihr werdet uns unterstützen.", sourceObjective = "Findet Silithyst, bringt es zum Silithystextraktor und sprecht anschließend mit General Kirika beim Lager der Horde in der Nähe des Regalschwarmbaus.", progress = "Hütet Euch vor den Gefahren der Wüste, {name}. Die Allianz könnte hinter jeder Düne lauern und jeder Schritt könnte somit Euer letzter sein.", completion = "Ausgezeichnete Arbeit, {name}. Diese Ressourcen kommen sofort zum Rest der Vorräte. Jedes Bisschen trägt zu unserem Sieg und zur Schwächung unserer Feinde bei.", sourceObjectiveStatus = "unverified-source-field" }
quests[9556] = { id = 9556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Sieger...", description = "Ihr habt zweifellos lange und hart um die Verteidigung der Türme gekämpft, {race}. Wir würden Euch gerne etwas im Gegenzug für Euren tapferen Einsatz geben, allerdings müsst Ihr uns zuerst beweisen, dass Ihr die Gewichtigkeit dieser hier stattgefundenen Tragödien auch versteht.\n\nLauft durch Stratholme und sucht nach einer Phiole mit dem heiligen Wasser. Sobald Ihr sie gefunden habt, reist zum Magierviertel in Stormwind oder nach Undercity... Dort werdet Ihr, insofern Ihr in diesen Landen siegreich wart, auf meinen Kollegen treffen.", sourceObjective = "Sucht nach einer Phiole mit heiligem Wasser in Stratholme und bringt sie zu dem Magier von Lordaeron im Magierviertel von Stormwind oder in Undercity, falls Eure Seite in den östlichen Pestländern erfolgreich war.", sourceObjectiveStatus = "unverified-source-field" }
quests[9664] = { id = 9664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Befestigungen", description = "Willkommen in den Pestländern, {name}. Wie Ihr wisst, behaupten sich die Verlassenen und ihre Verbündeten entgegen all unserer Anstrengungen in den von hier aus westlich gelegenen Ländern. Die Kommandanten der Allianz haben beschlossen, dass hier im Osten neue Befestigungen errichtet werden sollen, um die Schlinge um unseren Feind noch etwas enger zu schnüren.\n\nLange seit den Tagen Lordaerons verlassene und herrenlose Türme müssen für diesen Zweck erobert und wieder aufgebaut werden. Diese Länder hier ist gefährlich, wir berauchen Eure Hilfe", sourceObjective = "Erobert den Turm der Kronenwache, den Ostwallturm, den Nordpassturm und den Pestwaldturm in den östlichen Pestländern. Kehrt anschließend zum Abgesandten Whitebeard bei der Kapelle des hoffnungsvollen Lichts zurück.", completion = "Sehr gut, {name}. Es ist äußerst wichtig, dass wir diese Türme halten. Wir müssen sie vor zukünftigen Angriffen schützen und brauchen noch so lange Eure Hilfe, bis Verstärkung zur Sicherung dieses Gebiets eintrifft.", sourceObjectiveStatus = "unverified-source-field" }
quests[9665] = { id = 9665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung der Verteidigung", description = "Agenten der Verlassenen sind hinter das Vorhaben der Allianz gekommen. Sie wollen neue Stützpunkte bei verlassenen Türmen hier in den östlichen Pestländern einrichten.\n\nWir dürfen auf keinen Fall zulassen, dass sie sich an unserer östlichen Grenze dauerhaft festsetzen, wir müssen den Einfall der Allianz abwehren. Wir beabsichtigen sie aus jeglichen Türmen, die sie bereits besetzt haben, zu vertreiben. Dann gilt es diese Türme zu verteidigen und weitere Eroberungsversuche abzuwehren.", sourceObjective = "Erobert den Turm der Kronenwache, den Ostwallturm, den Nordpassturm und den Pestwaldturm in den östlichen Pestländern. Kehrt anschließend zum Abgesandten Gormok bei der Kapelle des hoffnungsvollen Lichts zurück.", completion = "Das sind gute Neuigkeiten, {name}. Bis wir die Kräfte der Allianz gänzlich vertrieben haben, wird es hier in den Pestländern dauerhaft zu Kämpfen kommen.\n\nIch hoffe, dass Ihr uns bis zu diesem Tag auch noch weiterhin unterstützt.", sourceObjectiveStatus = "unverified-source-field" }
quests[65593] = { id = 65593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herzen der Liebenden", description = "Ein Inkubus wird von den Herzen Liebender angelockt. Die sehnlichste Liebe erschafft einen unwiderstehlichen Köder.\n\nMeine Wahrsagung hat mir zwei Personen gezeigt, die ganz besonders geeignet sein sollten.\n\nIm Silberwald bietet Avelina Lilly den gefallenen Magiern von Ambermill ihre Dienste als Schneiderin an. Im Brachland hofft Isaac Pearson, sich im Küstendorf Ratchet einen Namen zu machen.\n\nSie arbeiten an entgegengesetzten Enden der Welt, doch ihre Herzen sehnen sich nur nach einander. Bringt ihre Herzen zu Carendin.", sourceObjective = "Bringt die Herzen von Avelina Lilly und Isaac Pearson zu Carendin Halgar im Tempel der Verdammten.", progress = "Ah, {name}, Ihr seid zurückgekehrt. Konntet Ihr die Herzen der Liebenden beschaffen?", completion = "Hervorragend gemacht, wie erwartet, {name}.\n\n\n\nTrottel.", sourceObjectiveStatus = "unverified-source-field" }
quests[65597] = { id = 65597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bindung", description = "Endlich ist es so weit. Bringt die Herzen zum Beschwörungskreis dort unten. Legt sie in die Mitte und ruft den Inkubus herbei.\n\nDer Dämon wird wenig erfreut sein, wenn er merkt, dass Ihr ihn in eine Falle gelockt habt. Lasst Euch nicht von ihm bezaubern, {name}. Ihr müsst ihn vollständig unterwerfen.\n\nErst dann kann ich Euch den Zauber lehren, mit dem Ihr ihn an Euren Willen bindet.", sourceObjective = "Beschwört mit den Herzen der Liebenden einen Inkubus, unterwerft ihn und bringt die Herzen der Liebenden dann zu Carendin Halgar im Magieviertel von Undercity zurück.", progress = "Der Inkubus beherrscht durchaus Kampfkünste, doch seine stärkste Waffe ist sein täuschender Charme. Ein Augenblick der Schwäche reicht, um von diesem Dämon betört zu werden.\n\nLasst das nicht zu, {name}.", completion = "Beeindruckend. Wirklich beeindruckend. Die Sayaad sind darauf spezialisiert, Sterbliche zu ihren Opfern zu machen. Viele {class}, die sich stark genug wähnten, um einen zu beherrschen, wurden stattdessen beherrscht.\n\nIhr habt der Prüfung standgehalten, {name}, und Euch Eure Belohnung verdient. Ich werde Euch den Zauber zur Beschwörung eines Inkubus lehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[65601] = { id = 65601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liebe kann schmerzhaft sein", description = "Einen männlichen Sayaad nennt man einen Inkubus. Eine äußerst boshafte Kreatur, die nur eines im Sinn hat.\n\nDer Dämon muss mit einem Köder in unsere Welt gelockt werden, mit einem Gegenstand, der starke Liebe und Hingabe verkörpert.\n\nWenn Ihr Euch von einem Blinden führen lassen möchtet, {name}, dann hört zu. Östlich von der Kluft der Schatten, in der Gasse von Orgrimmar, lebt Magar. Er wartet darauf, dass sein Lebensgefährte Krilge zurückkehrt.\n\nGeht zu ihm. Er wird Euch bitten, etwas Wertvolles zu suchen. Dies wird der Schlüssel sein, den Ihr dann Gan'rul bringen müsst.", sourceObjective = "Sprecht mit Magar in Orgrimmar.", completion = "Wer hat Euch von Krilge erzählt? Habt Ihr Neuigkeiten? Ihr treibt hoffentlich keine Spielchen mit mir...", sourceObjectiveStatus = "unverified-source-field" }
quests[65602] = { id = 65602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles aus Liebe", description = "Ihr werdet ein mächtiges Reagenz brauchen, um einen Inkubus anzulocken. Ein Objekt, das große Hingabe und Liebe verkörpert.\n\nDurch Wahrsagung habe ich eine kleine Statuette ausfindig gemacht, die für Euer Ritual geeignet sein sollte.\n\nVor Jahrtausenden gehörte die Figur einem jungen Paar. Die ursprünglichen Eigentümer sind verstorben, doch dieses Andenken besteht bis heute.\n\nFolgt der Straße nach Norden ins Ashenvale, dann Richtung Westen und an Maestras Posten vorbei. Ihr werdet ein Haus zwischen den Bäumen sehen. Dort findet Ihr, was Ihr sucht.", sourceObjective = "Beschafft die Holzstatuette und bringt sie zu Gakin dem Dunkelbinder im Magierviertel von Stormwind.", progress = "Ihr seid zurück. Darf ich davon ausgehen, dass Ihr Erfolg hattet?", completion = "<Gakin dreht und wendet die Holzstatuette in seiner Hand.>\n\nIch kann die Energie der Emotionen in diesem Artefakt spüren. Die Zeit konnte ihm nichts anhaben. Es wird den Inkubus anlocken wie eine Blüte die Biene.\n\nAuf Takar kann man sich verlassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65603] = { id = 65603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bindung", description = "Es ist so weit. Nehmt die Statuette und steigt in die Gruft hinab. Ein Beschwörungskreis ist bereits vorbereitet. Ihr müsst die Statuette in der Mitte platzieren.\n\nDann wird sich das Tor öffnen und der Inkubus wird in unsere Welt kommen.\n\nIhr dürft einen Sayaad nicht unterschätzen. Der Dämon wird Euch angreifen, sobald er Eure Täuschung bemerkt. Ihr müsst alles einsetzen, was Ihr gelernt habt, um ihn zu besiegen.\n\nWenn Ihr Erfolg habt, kehrt zu mir zurück und ich unterwerfe die Kreatur Eurem Willen. Wenn Ihr versagt, ist Eure Seele verwirkt.", sourceObjective = "Beschwört mit Hilfe der Holzstatuette einen Inkubus, unterwerft ihn und bringt dann die Holzstatuette zu Gakin dem Dunkelbinder im geschlachteten Lamm zurück.", progress = "Der Inkubus wird versuchen, Euch zu betören, zu täuschen und so zu überrumpeln. Der Dämon weiß genau, wie er die Herzen Sterblicher für sich gewinnt.\n\nDenkt daran, dass alle seine Versprechen Lügen sind. Für diesen Dämon seid Ihr nichts als Beute.", completion = "Nicht übel, {name}. Ihr habt das Scheusal bezwungen und Euer Wille blieb ungebrochen.\n\nManch ein {class} hielt sich schon für stark genug, einen Sayaad an sich zu binden, und endete stattdessen als nächste Mahlzeit des Dämons. Es freut mich, dass Ihr nicht so töricht seid.\n\nSeht genau zu, dann lehre ich Euch die Anrufung, mit der Ihr Euren jetzt unterworfenen Inkubus beschwört.", sourceObjectiveStatus = "unverified-source-field" }
quests[65604] = { id = 65604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bindung", description = "Ja... verstehe. Ich kann die verbleibenden Emotionen spüren, die in diesem Stoff enthalten sind. Er ist mit Liebe verwoben. Dem wird der Inkubus nicht widerstehen können.\n\nBringt dies zum Beschwörungskreis in Neerus Zelt, {name}. Beschwört einen boshaften Inkubus und zeigt ihm, dass Ihr Eure Fähigkeiten gemeistert habt. Rechnet damit, dass er sich nicht still und leise unterwerfen lässt. Haltet Eure Magie bereit und macht Euch auf einen Kampf gefasst. Schon so mancher Hexenmeister hat seinen letzten Fehler begangen, indem er einen Dämon unterschätzt hat.\n\nBringt den Stoff zu mir zurück, sobald Ihr ihn bezwungen habt. Ich werde Magar sagen, was Ihr herausgefunden habt.", sourceObjective = "Beschwört mithilfe des abgetragenen Schals einen Inkubus, unterwerft ihn und bringt dann den abgetragenen Schal zu Gan'rul Bloodeye in Orgrimmar zurück.", progress = "Die Sayaad unterwerfen den Verstand und quälen Seelen. Ihr Antlitz erfreut das Herz, sodass Ihr wehrlos seid, wenn sie mit Peitschen und Klauen in Euer Fleisch reißen.\n\nLasst Euch vom Inkubus nicht betören, {name}. Tötet ihn schnell und bringt es zu Ende.", completion = "Ha! Siegreich, wie ich es erwartet hatte!\n\nDer Inkubus wurde bezwungen, und ich werde Euch mit Freuden lehren, wie man den Dämon beschwört. Ihr werdet stärker und steht zweifelsohne davor, noch größere Macht zu erschließen.\n\nIch werde Magar den Schal zurückbringen. Ich kenne diesen Orc schon seit vielen Jahren und hätte nie gedacht, dass ihm einmal jemand so wie Krilge am Herzen liegen würde.\n\nDas erinnert uns daran, was uns von den Dämonen unterscheidet. Wir nutzen ihre Dunkelheit, lassen uns aber niemals von ihnen nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[65610] = { id = 65610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irgendwo anders", description = "Ich habe Krilge bei der Herstellung von Mondstoff im Ashenvale kennengelernt. Er war dort stationiert, um Zivilisten vor Gefahren zu beschützen, bis er dann verschwand...\n\nSie haben die Suche aufgegeben und sehen ihn als Deserteur, aber das glaube ich nicht.\n\nWir haben uns oft am Fallenskysee getroffen, bevor der von diesen aggressiven Sumpfmonstern überrannt wurde.\n\nIch bitte nur ungern andere um Gefallen, aber wenn Ihr ins Ashenvale gehen und nach ihm Ausschau halten könntet, wäre ich Euch dankbar.", sourceObjective = "Untersucht den Fallenskysee in Ashenvale und erstattet Gan'rul Bloodeye in Orgrimmar Bericht.", progress = "Ja, was gibt's?", completion = "Was habt Ihr da, {name}? Einen Schal aus... Mondstoff? Ihr wollt mich doch hoffentlich nicht bezirzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[76156] = { id = 76156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schleicht mit der Erdenmutter", description = "Ich spüre ein verborgenes Talent für die subtilen Künste in Euch, <Schamane/Schamanin>. Nutzt diese Maske, um die nahegelegene Mine der Venture Company zu infiltrieren und ihre Vorräte zu stehlen. Das mag nicht nach einer überzeugenden Verkleidung aussehen, aber ein fähiger Schurke kann sich mit so wenig wie einem charmanten Lächeln und einer klugen Ablenkung an jeder Wache vorbeischleichen. Ich bin überzeugt, Ihr besitzt diese Fähigkeit ebenfalls.", sourceObjective = "Schleicht Euch in die Mine der Venture Company südöstlich von Thunder Bluff und sammelt 5 Zephyriumbergbauladung aus Loren mit Sprengvorräten, dann kehrt zu Eberton Schattentotem in Thunder Bluff zurück.", progress = "Wir müssen an Euren Schleichfähigkeiten arbeiten, {class}. Ich konnte Euch hören, sobald Ihr die Ebene betreten habt.", completion = "Hmm... Vielleicht sind Verkleidungen nicht Eure Stärke.", sourceObjectiveStatus = "unverified-source-field" }
quests[76160] = { id = 76160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schleicht mit der Erdenmutter", description = "Ich spreche aus einer Zukunft zu Euch, in der die Horde vor Bedrohungen steht, die Ihr Euch nicht vorstellen könnt. Da die anderen mich nicht sehen können, muss ich mich darauf verlassen, dass Ihr meine Fähigkeiten lernt und sie an den Stamm weitergebt.\n\nVielleicht könnt Ihr besser mit Giften umgehen als mit Verkleidungen. Die Harpyien im Norden nisten in einem Baum, der ein stark toxisches Harz produziert. Sammelt die heruntergefallenen Zapfen um die Nester herum auf, dann zerstampft sie zu einer Salbe. Wenn Ihr sie auf eine Klinge auftragt, wird sie sich in das Fleisch Eurer Feinde brennen und ihr Blut in Salz verwandeln.", sourceObjective = "Sammelt 8 Windzornzapfen nördlich von Thunder Bluff, zerstampft sie mit Mörser und Stößel und kehrt mit dem Ergebnis zu Eberton Schattentotem in Thunder Bluff zurück.", progress = "Passt mit der fertigen Salbe gut auf, {class}. Jeder Hautkontakt könnte sehr schmerzhaft sein.", completion = "{class}, das ist nicht die giftige Salbe, um die ich Euch gebeten habe. Was Ihr mir gebracht habt, ist nichts weiter als Piniennussbutter. Seid Ihr sicher, dass Ihr meinen Anweisungen gefolgt seid?\n\nDas eignet sich mehr als Brotaufstrich und weniger als Waffengift. Es sei denn, Euer Gegner hat zufällig eine schwere Nussallergie.", sourceObjectiveStatus = "unverified-source-field" }
quests[76240] = { id = 76240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schleicht mit der Erdenmutter", description = "Ich habe noch eine letzte Idee, die uns zum Erfolg führen könnte. Ich spüre immer noch ein verborgenes Talent in Euch, aber vielleicht müssen wir es indirekter herauslocken.\n\nGeht und besorgt einen rohen glänzenden Kleinfisch. Bringt ihn her und nutzt diese Dolche, um ihn zu säubern und zu filetieren. Denkt nicht zu viel darüber nach. Tut einfach, was sich natürlich anfühlt.", sourceObjective = "Kauft oder fangt einen rohen glänzenden Kleinfisch, dann nutzt das Messerset, um ihn vor Eberton Schattentotem in Thunder Bluff zu filetieren.", progress = "Habt Ihr etwas für mich?", completion = "Das war eine starke Leistung, {class}. Nicht ganz die schurkische Präzision, die ich mir erhofft hatte, aber Ihr besitzt eine beeindruckende Fingerfertigkeit.\n\nJetzt sehe ich, dass nicht Ihr mein Volk in den subtilen Künsten ausbilden werdet, aber es gibt eine Sache, die ich Euch beibringen kann. Viel Glück auf Euren Reisen, {class}. Die Horde wird Helden wie Euch brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[77568] = { id = 77568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stärke eines Jägers", description = "Ein Jäger zieht seine Kraft nicht nur aus seinen Begleitern, sondern aus der Verbindung mit allen Wesen und dem Respekt für sie. Ihr werdet viele Tiere im Dienst für die Allianz jagen und erlegen, aber selbst im Kampf müsst Ihr Euren Gegner respektieren.\n\nMein letzter Lehrling nutzte eine mystische Rune, um ihre Fähigkeiten zu verstärken, aber leichtsinnigerweise wollte sie sie gleich an der größten Spinne der Höhle im Norden ausprobieren: einer Kreatur, die wir Githyiss die Üble nennen. Ihre Respektlosigkeit hatte ihr Ableben zur Folge.\n\nTötet Githyiss, aber unterschätzt ihre Stärke nicht.", sourceObjective = "Besiegt Githyiss die Üble in der Schattenweberhöhle und bergt die verlorene Rune. Lernt die Rune, dann erstattet Ayanna Everstride in Shadowglen Bericht.", completion = "Gut gemacht, {name}. Die Anwendung der Rune auf Eure Ausrüstung wird Euch mächtige neue Fähigkeiten gewähren.\n\nEs gibt viele solcher Runen in ganz Azeroth. Sucht nach ihnen, sie werden Euch auf Eurer Reise eine gute Hilfe sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[77571] = { id = 77571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relikte der Kaldorei", description = "Die Kaldorei sind ein uraltes Volk und unsere verlorenen Relikte können auf ganz Azeroth gefunden werden. Mithilfe dieser Relikte können die Geister Euch beibringen, wie Ihr Eure Verbindung zum Traum stärken könnt.\n\nDie Grellkin haben ein solches Relikt gestohlen. Tötet sie und bergt das Relikt. Dann folgt seiner Führung und erlernt eine neue Kampftechnik. Kehrt zu mir zurück, wenn Ihr fertig seid.", sourceObjective = "Bergt das Relikt von den Grellkin in Shadowglen. Folgt der Führung des Relikts und lernt eine neue Fähigkeit, dann erstattet Mardant Strongoak Bericht.", progress = "Was hat das Relikt Euch gelehrt?", completion = "Gut gemacht, {name}. Die Rune, die Ihr erlernt habt, auf Eure Ausrüstung anzuwenden, wird Euch mächtige neue Fähigkeiten verleihen.\n\nHaltet auf Euren Reisen Ausschau nach weiteren unserer verlorenen Relikte.", sourceObjectiveStatus = "unverified-source-field" }
quests[77573] = { id = 77573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zweistöckige Arbeit", description = "Ich habe eine Übung für Euch vorbereitet, {name}. Auf dem Dach dieses Gebäudes befindet sich ein Eulengötze. Ihr solltet ihn vom Südeingang aus sehen können. Der Götzen hat ein Geheimfach mit einer geschnitzten Rune.\n\nKlettert auf das Dach, findet und lernt die Rune, die im Götzen versteckt ist, dann kommt zu mir zurück.", sourceObjective = "Bergt die Rune aus dem versteckten Götzen und nutzt sie, um eine neue Fähigkeit zu lernen. Kehrt danach zu Frahun Shadewhisper zurück.", completion = "Gut gemacht, {name}. Die Anwendung der Rune auf Eure Ausrüstung wird Euch mächtige neue Fähigkeiten gewähren.\n\nEs gibt viele solcher Runen in ganz Azeroth. Sucht nach ihnen, sie werden Euch auf Eurer Reise eine gute Hilfe sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[77574] = { id = 77574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meditation über Elune", description = "Der Allianz beizutreten, hat unser Volk gestärkt, aber wir dürfen nicht vergessen, dass wir Kaldorei sind. Unsere Verbindung zu Elune ist der Kern unseres Wesens.\n\nBefreit Euren Geist, {name}, und konzentriert Euch ganz auf meine Stimme. Ich werde eine uralte Erinnerung unseres Volkes mit Euch teilen. Geht zum Mondbrunnen im Norden und kniet im heiligen Wasser nieder, um über Elunes Geheimnisse zu meditieren. Wenn Ihr Eure Gedanken fokussiert habt, werdet Ihr diese Erinnerung verstehen und eine neue Technik lernen. Kommt zu mir zurück, wenn Ihr fertig seid.", sourceObjective = "Kniet im Mondbrunnen nieder und meditiert über Elune, dann nutzt die Erinnerung, um eine neue Fähigkeit zu lernen. Kehrt anschließend zu Shanda in Shadowglen zurück.", completion = "Elune wird Euch auf Euren Reisen wahrscheinlich weitere Erinnerungen offenbaren. Ihr könnt an allen Mondbrunnen in Azeroth meditieren, um Eure Gedanken zu klären und diese Erinnerungen zu interpretieren.\n\nKomplexere Visionen zu verstehen, könnte Hilfe von anderen Priestern der Allianz erfordern. Schämt Euch nicht, von ihrem Glauben zu lernen, {name}. Tyrande lehrt uns, dass das heilige Licht, das die Menschen verehren, und das Licht von Elune eng miteinander verwandt sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[77575] = { id = 77575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unter den Schattenweben", description = "Die Krieger der Allianz haben Euch viel zu lehren, aber Ihr müsst auch selbst neue Techniken suchen.\n\nIm Norden gibt es eine Höhle, die von Waldweberspinnen befallen ist. Ein anderer Jungkrieger ist vor Kurzem in die Höhle gereist, aber nie zurückgekehrt. Er hat damit experimentiert, mystische Runen in seine Ausrüstung zu gravieren, um seine Kampffertigkeiten zu verbessern.\n\nFindet die Rune bei den Spinnen und lernt die Technik selbst.", sourceObjective = "Tötet Waldweberspinnen in der Schattenweberhöhle und bergt die verlorene Rune. Erlernt die Rune und erstattet Alyissia in Shadowglen Bericht.", completion = "Gut gemacht, {name}. Die Anwendung der Rune auf Eure Ausrüstung wird Euch mächtige neue Fähigkeiten gewähren.\n\nEs gibt viele solcher Runen in ganz Azeroth. Sucht nach ihnen, sie werden Euch auf Eurer Reise eine gute Hilfe sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[77582] = { id = 77582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eignungsprüfung", description = "Ein Krieger der Horde muss vor allem körperliche Stärke besitzen. Auf Eurer Reise werdet Ihr viele Prüfungen Eurer Ausdauer überstehen müssen.\n\nZu diesem Zweck habe ich eine Truhe an den Klippen hinter mir versteckt. Ihr könnt sie vom Feuer in der Mitte des Dorfes aus sehen. Sie zu erreichen, wird nicht so einfach werden. In der Truhe befindet sich eine mächtige Rune.\n\nEure Prüfung besteht darin, die Rune zu finden und zu mir zurückzukehren, nachdem Ihr ihre Geheimnisse entschlüsselt habt.", sourceObjective = "Findet die versteckte Truhe in den Klippen hinter Frang. Lernt die Rune, die sich darin befindet, und erstattet Frang im Tal der Prüfungen Bericht.", completion = "Gut gemacht, {name}. Die Anwendung der Rune auf Eure Ausrüstung wird Euch mächtige neue Fähigkeiten gewähren.\n\nEs gibt viele solcher Runen in ganz Azeroth. Sucht nach ihnen, sie werden Euch auf Eurer Reise eine gute Hilfe sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[77583] = { id = 77583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oben auf den Klippen", description = "Ich habe eine Übung für Euch vorbereitet, {name}. Ich habe eine Truhe an den Klippen hinter mir versteckt. Ihr könnt sie vom Feuer in der Mitte des Dorfes aus sehen. In der Truhe befindet sich eine mächtige Rune.\n\nEure Prüfung besteht darin, die Rune zu bergen und zu mir zurückzukehren, nachdem Ihr ihre Geheimnisse entschlüsselt habt.", sourceObjective = "Findet die versteckte Truhe in den Klippen um das Tal der Prüfungen. Lernt die Rune, die sich darin befindet, und erstattet Rwag im Höhlenbau Bericht.", completion = "Gut gemacht, {name}. Die Anwendung der Rune auf Eure Ausrüstung wird Euch mächtige neue Fähigkeiten gewähren.\n\nEs gibt viele solcher Runen in ganz Azeroth. Sucht nach ihnen, sie werden Euch auf Eurer Reise eine gute Hilfe sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[77584] = { id = 77584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagd auf die Rune", description = "Ein Jäger zieht seine Stärke aus seiner Verbindung mit der Natur. Auf Eurer Reise werdet Ihr viel unwegsames Terrain durchqueren müssen und mithilfe Eures Verstandes überleben.\n\nVor Kurzem ist leider ein Jungjäger daran gescheitert. Er ging auf die Jagd nach Skorpiden, doch er kehrte nie zurück. Er hat damit experimentiert, mystische Runen in seine Ausrüstung zu gravieren, um seine Kampffertigkeiten zu verbessern.\n\nFindet die Rune bei den Skorpiden in der Nähe und kehrt zu mir zurück, wenn Ihr ihre Geheimnisse entschlüsselt habt.", sourceObjective = "Findet die verlorene Rune, indem Ihr Skorpiden im Tal der Prüfungen tötet. Erlernt die Macht der Rune, dann erstattet Jen'shan Bericht.", completion = "Gut gemacht, {name}. Die Anwendung der Rune auf Eure Ausrüstung wird Euch mächtige neue Fähigkeiten gewähren.\n\nEs gibt viele solcher Runen in ganz Azeroth. Sucht nach ihnen, sie werden Euch auf Eurer Reise eine gute Hilfe sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[77585] = { id = 77585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbole der Macht", description = "Schamanismus ist eine uralte Kunst, {name}. Viele Artefakte voll spiritueller Energie können auf ganz Azeroth gefunden werden. Ich habe vor Kurzem selbst ein Symbol bemerkenswerter Macht gefunden, aber diese lästigen Skorpiden haben es gestohlen.\n\nEiner von ihnen trägt es wahrscheinlich noch mit sich herum und hält es für funkelnde Nestdekoration.\n\nWenn Ihr das Symbol findet, erlernt seine Macht und kehrt zu mir zurück.", sourceObjective = "Findet das gestohlene Symbol, indem Ihr Skorpiden im Tal der Prüfungen tötet. Erlernt seine Macht, dann erstattet Shikrik Bericht.", completion = "Gut gemacht, {name}. Die Anwendung der Rune auf Eure Ausrüstung wird Euch mächtige neue Fähigkeiten gewähren.\n\nEs gibt viele solcher Runen in ganz Azeroth. Sucht nach ihnen, sie werden Euch auf Eurer Reise eine gute Hilfe sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[77586] = { id = 77586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestohlene Macht", description = "Ich habe mit einer neuen Art von Magie experimentiert, mit einer Rune, die Teufelsenergie kanalisieren kann, um mächtige Zauber zu wirken. Ich würde diese Macht mit Euch teilen, aber sie wurde mir von einem dieser lästigen Familiaren der Burning Blade gestohlen.\n\nGeht zu ihrem Koven im Norden und seht nach, ob Ihr meine Rune irgendwo zwischen ihren Habseligkeiten findet. Meiner Erfahrung nach verstecken die Familiare ihre Beute sehr gut.\n\nMeldet Euch wieder bei mir, sobald Ihr sie gefunden und ihre Magie gelernt habt. Es würde mir Freude bereiten zu sehen, dass mein Experiment genutzt wird.", sourceObjective = "Findet die gestohlene Rune im Koven der Burning Blade. Erlernt ihre Macht, dann erstattet Nartok im Höhlenbau Bericht.", completion = "Gut gemacht, {name}. Die Anwendung der Rune auf Eure Ausrüstung wird Euch mächtige neue Fähigkeiten gewähren.\n\nEs gibt viele solcher Runen in ganz Azeroth. Sucht nach ihnen, sie werden Euch auf Eurer Reise eine gute Hilfe sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[77587] = { id = 77587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbole der Macht", description = "Schamanismus ist eine uralte Kunst, {name}. Viele Artefakte voll spiritueller Energie können auf ganz Azeroth gefunden werden. Ich habe vor Kurzem selbst ein Symbol bemerkenswerter Macht gefunden, aber diese lästigen Skorpiden haben es gestohlen.\n\nEiner von ihnen trägt es wahrscheinlich noch mit sich herum und hält es für funkelnde Nestdekoration.\n\nWenn Ihr das Symbol findet, erlernt seine Macht und kehrt zu mir zurück.", sourceObjective = "Findet das gestohlene Symbol, indem Ihr Skorpiden im Tal der Prüfungen tötet. Erlernt seine Macht, dann erstattet Shikrik Bericht.", completion = "Gut gemacht, {name}. Die Anwendung der Rune auf Eure Ausrüstung wird Euch mächtige neue Fähigkeiten gewähren.\n\nEs gibt viele solcher Runen in ganz Azeroth. Sucht nach ihnen, sie werden Euch auf Eurer Reise eine gute Hilfe sein.", sourceObjectiveStatus = "unverified-source-field" }
