quests[77590] = { id = 77590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unwegsames Terrain", description = "Ein Jäger zieht seine Stärke aus seiner Verbindung mit der Natur. Auf Eurer Reise werdet Ihr viel unwegsames Terrain durchqueren müssen und mithilfe Eures Verstandes überleben.\n\nVor Kurzem ist leider ein Jungjäger daran gescheitert. Er ging auf die Jagd nach Skorpiden, doch er kehrte nie zurück. Er hat damit experimentiert, mystische Runen in seine Ausrüstung zu gravieren, um seine Kampffertigkeiten zu verbessern.\n\nFindet die Rune bei den Skorpiden in der Nähe und kehrt zu mir zurück, wenn Ihr ihre Geheimnisse entschlüsselt habt.", sourceObjective = "Findet die verlorene Rune, indem Ihr Skorpiden im Tal der Prüfungen tötet. Erlernt die Macht der Rune, dann erstattet Jen'shan Bericht.", completion = "Gut gemacht, {name}. Die Anwendung der Rune auf Eure Ausrüstung wird Euch mächtige neue Fähigkeiten gewähren.\n\nEs gibt viele solcher Runen in ganz Azeroth. Sucht nach ihnen, sie werden Euch auf Eurer Reise eine gute Hilfe sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[77592] = { id = 77592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oben auf den Klippen", description = "Ich habe eine Übung für Euch vorbereitet, {name}. Ich habe eine Truhe an den Klippen hinter mir versteckt. Ihr könnt sie vom Feuer in der Mitte des Dorfes aus sehen. In der Truhe befindet sich eine mächtige Rune.\n\nEure Prüfung besteht darin, die Rune zu bergen und zu mir zurückzukehren, nachdem Ihr ihre Geheimnisse entschlüsselt habt.", sourceObjective = "Findet die versteckte Truhe in den Klippen um das Tal der Prüfungen. Lernt die Rune, die sich darin befindet, und erstattet Rwag im Höhlenbau Bericht.", completion = "Gut gemacht, {name}. Die Anwendung der Rune auf Eure Ausrüstung wird Euch mächtige neue Fähigkeiten gewähren.\n\nEs gibt viele solcher Runen in ganz Azeroth. Sucht nach ihnen, sie werden Euch auf Eurer Reise eine gute Hilfe sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[77616] = { id = 77616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlorene Rune", description = "Die Krieger der Allianz haben Euch viel beizubringen, aber Ihr müsst auch selbst nach neuen Techniken suchen.\n\nEine andere junge Kriegerin ist vor Kurzem in die Echokammmine gereist. Sie hat damit experimentiert, mystische Runen in ihre Ausrüstung zu gravieren, um ihre Kampffertigkeiten zu verbessern.\n\nIch fürchte, sie wurde überwältigt, als die Kobolde die Mine eingenommen haben. Findet die Rune bei den Kobolden und lernt die Technik selbst.", sourceObjective = "Findet die verlorene Rune in der Echokammmine und nutzt sie, um eine neue Fähigkeit zu lernen. Erstattet anschließend Llane Beshere in Nordhain Bericht.", completion = "Gut gemacht, {name}. Die Anwendung der Rune auf Eure Ausrüstung wird Euch mächtige neue Fähigkeiten gewähren.\n\nEs gibt viele solcher Runen in ganz Azeroth. Sucht nach ihnen, sie werden Euch auf Eurer Reise eine gute Hilfe sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[77617] = { id = 77617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relikte des Lichts", description = "Relikte des Lichts können auf ganz Azeroth gefunden werden. Diese Relikte, vor allem die Buchbände, die unseren Orden seit seiner Gründung geleitet haben, können Euch helfen, Eure Verbindung zum Licht zu stärken.\n\nEin solcher Buchband war in den Archiven der Abtei gelagert, aber er wurde von den Banditen der Defias im Osten gestohlen. Holt den Buchband zurück, dann studiert seine Anleitungen, um eine neue Kampftechnik zu lernen. Kehrt zu mir zurück, wenn Ihr fertig seid.", sourceObjective = "Findet den Buchband und folgt seiner Anleitung, um eine neue Fähigkeit zu lernen, dann kehrt zu Bruder Sammuel in Nordhain zurück.", progress = "Was hat der Buchband Euch beigebracht, {name}?", completion = "Gut gemacht, {name}. Die Rune, die Ihr erlernt habt, auf Eure Ausrüstung anzuwenden, wird Euch mächtige neue Fähigkeiten verleihen.\n\nHaltet auf Euren Reisen Ausschau nach weiteren dieser verlorenen Relikten.", sourceObjectiveStatus = "unverified-source-field" }
quests[77618] = { id = 77618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreimal geklaut", description = "Ich schäme mich, das zuzugeben, {name}, aber diese Idioten der Defias haben mich übers Ohr gehauen. Sie haben eine magische Rune gestohlen, die ich mir... ähm, aus der Abtei \"geliehen\" habe. Ich dachte, damit könnte ich mir einen schnellen Vorteil verschaffen, aber ich konnte sie nicht zum Funktionieren bringen.\n\nGeht nach Osten und versucht, sie unter ihrer Beute zu finden, ja? Und dann versucht selbst Euer Glück mit der Rune. Ihr seht mir aus wie ein Bücherwurm. Nicht böse gemeint.", sourceObjective = "Findet die verlorene Rune in den Lagern der Defias und lernt mit ihr eine neue Fähigkeit. Kehrt danach zu Jorik Kerridan in Nordhain zurück.", completion = "Ihr habt flinke Finger, {name}. Seht diese Rune als ein Geschenk.\n\nWenn Bruder Paxton fragt, haben wir uns nie gesprochen, alles klar?", sourceObjectiveStatus = "unverified-source-field" }
quests[77619] = { id = 77619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meditation über das Licht", description = "Das Licht hat mir Eure Zukunft gezeigt. Ihr werdet gegen die Kobolde in der Echokammmine kämpfen. In der Mine wird das Licht Euch eine Erinnerung der Vergangenheit offenbaren. Nachdem das geschehen ist, kehrt zur Abtei zurück und kniet in diesen Hallen nieder und meditiert über die Mysterien des Lichts.\n\nWenn Ihr Eure Gedanken fokussiert habt, werdet Ihr diese Erinnerung entziffern und eine neue Technik lernen können. Kehrt zu mir zurück, wenn Ihr fertig seid.", sourceObjective = "Tötet Kobolde in der Echokammmine, um eine Erinnerung zu erhalten. Kniet in der Abtei von Nordhain nieder, um über das Licht zu meditieren, dann nutzt die Erinnerung, um eine neue Fähigkeit zu lernen. Kehrt anschließend zu Priesterin Anetta zurück.", progress = "Was hat Euch das Licht gezeigt?", completion = "Wenn das Licht Euch weitere Visionen offenbart, könnt Ihr jederzeit an heiligen Orten meditieren, um Eure Gedanken zu klären und über diese Geheimnisse nachzudenken.\n\nIch habe auch gesehen, dass Euer Weg Euch zu einem Gespräch mit unseren elfischen Verbündeten in Kalimdor führen wird. Mehr über ihre merkwürdigen Rituale der Mondanbetung zu erfahren, könnte uns von Nutzen sein, um auch ihnen eines Tages den Weg zum Licht zu zeigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[77620] = { id = 77620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zauberforschung", description = "Ich werde Euch beibringen, was ich weiß, {name}, aber Eure eigenen Forschungen anzustellen, kann Euch unfassbar mächtig machen. Aufzeichnungen zu studieren, die Azeroths größte Erzmagier hinterlassen haben, ist ein guter Anfang. Die Archive der Abtei bargen eine Vielfalt an arkanen Forschungsnotizen, aber sie wurden von Agenten der Defias gestohlen.\n\nFindet die Zaubernotizen bei den Banditen im Osten und nutzt diese Fibel, um sie zu entziffern. Kehrt zu mir zurück, wenn Ihr Erfolg hattet.", sourceObjective = "Holt die Forschungsnotizen von den Banditen der Defias zurück und nutzt sie, um einen neuen Zauber zu lernen. Kehrt anschließend zu Khelden Bremen in Nordhain zurück.", progress = "Wie kommen Eure Forschungen voran?", completion = "Gut gemacht, {name}. Nehmt diese Verständnisamulette. Sie werden Euch dabei helfen, weitere arkane Schriften zu entziffern.\n\nSucht weiter nach Zaubernotizen in ganz Azeroth und nutzt sie, um Eure Forschung voranzubringen. Wenn Ihr mehr Amulette braucht, könnt Ihr diese bei einem Reagenzienverkäufer erwerben.", sourceObjectiveStatus = "unverified-source-field" }
quests[77621] = { id = 77621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestohlene Macht", description = "Ich habe mit einer neuen Art von Magie experimentiert, mit einer Rune, die Teufelsenergie kanalisieren kann, um mächtige Zauber zu wirken. Ich würde diese Macht mit Euch teilen, aber meine Notizen wurden mir letzte Nacht gestohlen. Ich verdächtige die Banditen, die sich \"Defias\" nennen.\n\nGeht nach Osten und seht nach, ob Ihr meine Rune irgendwo zwischen ihren Habseligkeiten findet. Meldet Euch wieder bei mir, sobald Ihr sie gefunden und ihre Magie gelernt habt. Es würde mir Freude bereiten zu sehen, dass mein Experiment genutzt wird.", sourceObjective = "Findet die Rune in den Lagern der Defias im Osten und lernt mit ihr eine neue Fähigkeit. Kehrt danach zu Drusilla La Salle in Nordhain zurück.", completion = "Ihr scheint Euch gut an diese neue Magie gewöhnt zu haben, {name}. Findet mehr dieser Runen und prägt sie in Eure Ausrüstung, um neue Fähigkeiten gegen diejenigen einzusetzen, die sich Euch widersetzen.\n\nEines Tages wird Eure Macht vielleicht selbst die meinige übertreffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[77642] = { id = 77642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weisheit der Loa", description = "Der Beitritt zur Horde hat unserem Volk eine sichere Heimat gegeben, {name}, aber wir müssen uns daran erinnern, dass es die Loa sind, die immer über uns wachen.\n\nKlärt Euren Geist, und ich werde eine uralte Erinnerung mit Euch teilen. Geht zum Loaaltar in Sen'jin und kniet davor nieder, um mit dem großen Loageist Zwiesprache zu halten. Wenn Ihr die Weisheit der Loa empfangen habt, werdet Ihr die Erinnerung verstehen, die ich Euch gegeben habe. Mit diesem Verständnis werdet Ihr eine neue Kraft entdecken.\n\nKehrt zu mir zurück, wenn Ihr fertig seid.", sourceObjective = "Kniet am Loaaltar in Sen'jin nieder und haltet mit dem Loageist Zwiesprache. Nutzt die Erinnerung, um eine neue Fähigkeit zu lernen, dann kehrt zu Ken'jal im Tal der Prüfungen zurück.", completion = "Gut gemacht, {name}. Die Rune auf Eure Ausrüstung anzuwenden, wird Euch mächtige neue Fähigkeiten verleihen.\n\nDie Loa werden Euch auf Euren Reisen viele weitere Erinnerungen offenbaren. Ihr könnt an Loaaltären auf ganz Azeroth beten, um Euren Geist zu klären und sie zu interpretieren, wie Ihr es gerade getan habt.\n\nUm komplexere Visionen zu verstehen, braucht Ihr vielleicht die Hilfe der {class} der Horde. Schämt Euch nicht, von ihrem Glauben zu lernen, {name}. Die Weisheit der Loa kann in allen Dingen gefunden werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[77643] = { id = 77643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zauberforschung", description = "Als <Magier/Magierin> werden Euch die arkanen Forschungen zu außerordentlicher Macht führen. Die Notizen zu studieren, welche die größten Magier Azeroths hinterlassen haben, ist ein großartiger Anfang. Ich hatte vor Kurzem selbst einige entdeckt, aber sie wurden von diesen lästigen Familiaren der Burning Blade gestohlen.\n\nHolt die Zaubernotizen aus dem Koven im Norden und benutzt diese Fibel, um sie zu entziffern. Kehrt zurück, wenn Ihr Eure Untersuchung abgeschlossen habt.", sourceObjective = "Findet die gestohlenen Zaubernotizen im Koven der Burning Blade, dann nutzt sie, um eine neue Fähigkeit zu lernen. Kehrt anschließend zu Mai'ah im Tal der Prüfungen zurück.", progress = "Wie kommen Eure Forschungen voran, {name}?", completion = "Gut gemacht, {name}. Nehmt diese Verständnisamulette. Sie werden Euch dabei helfen, weitere arkane Schriften zu entziffern.\n\nSucht weiter nach Zaubernotizen in ganz Azeroth und nutzt sie, um Eure Forschung voranzubringen. Wenn Ihr mehr Amulette braucht, könnt Ihr diese bei einem Reagenzienverkäufer erwerben.", sourceObjectiveStatus = "unverified-source-field" }
quests[77648] = { id = 77648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relikte der Tauren", description = "Die Tauren sind ein uraltes Volk, {name}, und unsere verlorenen Relikte können auf ganz Azeroth gefunden werden. Mithilfe dieser Relikte können die Geister Euch beibringen, wie Ihr Eure Verbindung zum Traum stärken könnt.\n\nDie Stacheleber der Borstennacken haben ein solches Relikt von uns gestohlen. Sie haben es bestimmt in die Dornrankenklamm gebracht. Bergt das Relikt und folgt seiner Führung, um eine neue Kampftechnik zu lernen. Kehrt zu mir zurück, wenn Ihr fertig seid.", sourceObjective = "Bergt das gestohlene Relikt aus der Dornrankenklamm. Folgt der Führung des Relikts und lernt eine neue Fähigkeit, dann erstattet Gart Mistrunner im Camp Narache Bericht.", completion = "Gut gemacht, {name}. Die Rune, die Ihr erlernt habt, auf Eure Ausrüstung anzuwenden, wird Euch mächtige neue Fähigkeiten verleihen.\n\nHaltet auf Euren Reisen Ausschau nach weiteren unserer verlorenen Relikte.", sourceObjectiveStatus = "unverified-source-field" }
quests[77649] = { id = 77649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stärke eines Jägers", description = "Jäger sind für die Lebensart der Tauren sehr wichtig, {name}. Unser Volk sieht zu uns als Wächter und Ernährer auf. Auf Euren Reisen werdet Ihr Euch häufig allein in feindlichen Gebieten wiederfinden und müsst Euch zum Überleben auf Eure Gerissenheit verlassen.\n\nVor Kurzem hat ein Jungjäger mit mystischen Runen experimentiert, um seine Kampffertigkeiten zu verbessern. Er ist ausgezogen, um sein Können an den Kampfebern der Borstennacken im Osten zu erproben, doch er kehrte nie zurück.\n\nFindet seine Rune und nutzt sie, um eine neue Kampftechnik zu lernen. Kehrt zu mir zurück, wenn Ihr fertig seid.", sourceObjective = "Findet die vermisste Rune, indem Ihr Kampfeber der Borstennacken in der Dornrankenklamm tötet. Nutzt die Rune, um eine neue Fähigkeit zu lernen, dann erstattet Lanka Farshot im Camp Narache Bericht.", completion = "Gut gemacht, {name}. Die Anwendung der Rune auf Eure Ausrüstung wird Euch mächtige neue Fähigkeiten gewähren.\n\nEs gibt viele solcher Runen in ganz Azeroth. Sucht nach ihnen, sie werden Euch auf Eurer Reise eine gute Hilfe sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[77651] = { id = 77651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Dornenranken", description = "Die Krieger der Horde haben Euch viel zu lehren, {name}, aber Ihr müsst auch selbst neue Techniken suchen.\n\nWie Ihr vielleicht wisst, gibt es eine Rotte feindlicher Stacheleber im Osten. Ein anderer Jungkrieger ist vor Kurzem in ihr Territorium vorgedrungen, aber nie zurückgekehrt. Er hat damit experimentiert, mystische Runen in seine Ausrüstung zu gravieren, um seine Kampffertigkeiten zu verbessern.\n\nFindet die Rune bei den Stachelebern und lernt die Technik selbst. Kehrt zu mir zurück, wenn Ihr fertig seid.", sourceObjective = "Findet die verlorene Rune in der Dornrankenklamm. Nutzt die Rune, um eine neue Fähigkeit zu lernen, dann erstattet Harutt Thunderhorn im Camp Narache Bericht.", completion = "Gut gemacht, {name}. Die Anwendung der Rune auf Eure Ausrüstung wird Euch mächtige neue Fähigkeiten gewähren.\n\nEs gibt viele solcher Runen in ganz Azeroth. Sucht nach ihnen, sie werden Euch auf Eurer Reise eine gute Hilfe sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[77652] = { id = 77652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbole der Macht", description = "Schamanismus ist eine uralte Kunst, {name}. Viele Artefakte voll spiritueller Energie können auf ganz Azeroth gefunden werden. Ich habe vor Kurzem selbst ein Symbol bemerkenswerter Macht gefunden, aber einige Stacheleber haben es gestohlen.\n\nGeht in ihr Territorium im Osten und findet das gestohlene Symbol. Einer ihrer Schamanen trägt es wahrscheinlich noch mit sich herum und versucht, seine Geheimnisse zu entschlüsseln.\n\nWenn Ihr das Symbol findet, erlernt seine Macht und kehrt zu mir zurück.", sourceObjective = "Bergt das verlorene Symbol von den Schamanen der Borstennacken in der Dornrankenklamm. Erlernt seine Macht und erstattet Harutt Thunderhorn im Camp Narache Bericht.", progress = "Habt Ihr das Symbol gefunden, {name}?", completion = "Gut gemacht, {name}. Die Anwendung der Rune auf Eure Ausrüstung wird Euch mächtige neue Fähigkeiten gewähren.\n\nEs gibt viele solcher Runen in ganz Azeroth. Sucht nach ihnen, sie werden Euch auf Eurer Reise eine gute Hilfe sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[77655] = { id = 77655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlorene Rune", description = "Die Krieger der Allianz haben Euch viel zu lehren, {name}, aber Ihr müsst auch selbst neue Techniken suchen.\n\nEs gibt eine Höhle voller Frostmanetrolle südlich von hier. Ein anderer Jungkrieger ist vor Kurzem hineingegangen, aber nie zurückgekehrt. Er hat damit experimentiert, mystische Runen in seine Ausrüstung zu gravieren, um seine Kampffertigkeiten zu verbessern.\n\nFindet die Rune bei den Trollen, einer von ihnen trägt sie wahrscheinlich mit sich herum, und lernt die Technik selbst. Kehrt zu mir zurück, wenn Ihr fertig seid.", sourceObjective = "Findet die verlorene Rune bei den Frostmanetrollen im Coldridgetal. Nutzt sie, um eine neue Fähigkeit zu lernen, dann erstattet Thran Khorman in Anvilmar Bericht.", completion = "Gut gemacht, {name}. Die Anwendung der Rune auf Eure Ausrüstung wird Euch mächtige neue Fähigkeiten gewähren.\n\nEs gibt viele solcher Runen in ganz Azeroth. Sucht nach ihnen, sie werden Euch auf Eurer Reise eine gute Hilfe sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[77656] = { id = 77656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlorene Rune", description = "Die Krieger der Allianz haben Euch viel zu lehren, {name}, aber Ihr müsst auch selbst neue Techniken suchen.\n\nEs gibt eine Höhle voller Frostmanetrolle südlich von hier. Ein anderer Jungkrieger ist vor Kurzem hineingegangen, aber nie zurückgekehrt. Er hat damit experimentiert, mystische Runen in seine Ausrüstung zu gravieren, um seine Kampffertigkeiten zu verbessern.\n\nFindet die Rune bei den Trollen, einer von ihnen trägt sie wahrscheinlich mit sich herum, und lernt die Technik selbst. Kehrt zu mir zurück, wenn Ihr fertig seid.", sourceObjective = "Findet die verlorene Rune bei den Frostmanetrollen im Coldridgetal. Nutzt sie, um eine neue Fähigkeit zu lernen, dann erstattet Thran Khorman in Anvilmar Bericht.", sourceObjectiveStatus = "unverified-source-field" }
quests[77657] = { id = 77657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relikte des Lichts", description = "Relikte des Lichts können auf ganz Azeroth gefunden werden. Diese Relikte, vor allem die Buchbände, die unseren Orden seit seiner Gründung geleitet haben, können Euch helfen, Eure Verbindung zum Licht zu stärken.\n\nEin solcher Buchband war in unseren Archiven gelagert, aber er wurde von Frostmanetrollen gestohlen. Der Dieb hat ihn wahrscheinlich noch bei sich. Holt den Buchband zurück, dann folgt seinen Anleitungen, um eine neue Kampftechnik zu lernen. Kehrt zu mir zurück, wenn Ihr fertig seid.", sourceObjective = "Holt den gestohlenen Buchband von den Frostmanetrollen im Coldridgetal zurück. Folgt seinen Anleitungen, um eine neue Fähigkeit zu lernen, dann kehrt zu Bromos Grummner in Anvilmar zurück.", completion = "Gut gemacht, {name}. Die Rune, die Ihr erlernt habt, auf Eure Ausrüstung anzuwenden, wird Euch mächtige neue Fähigkeiten verleihen.\n\nHaltet auf Euren Reisen Ausschau nach weiteren dieser verlorenen Relikten.", sourceObjectiveStatus = "unverified-source-field" }
quests[77658] = { id = 77658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreimal geklaut", description = "Ich schäme mich, das zuzugeben, {name}, aber diese Frostmanetrottel haben mich übers Ohr gehauen. Sie haben eine magische Rune gestohlen, die ich mir... ähm, aus der Schatzkammer \"geliehen\" habe. Ich dachte, das könnte mir sozusagen eine Starthilfe verschaffen, aber ich konnte sie nicht zum Funktionieren bringen.\n\nGeht in ihre Höhle im Süden und versucht, sie unter ihrer Beute zu finden, ja? Und dann versucht selbst Euer Glück mit der Rune. Ihr seht mir aus wie ein Bücherwurm. Nicht böse gemeint.", sourceObjective = "Holt die gestohlene Rune aus der Höhle der Frostmanetrolle im Coldridgetal. Setzt sie ein, um eine neue Fähigkeit zu lernen und kehrt zu Solm Hargrin in Anvilmar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[77659] = { id = 77659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreimal geklaut", description = "Ich schäme mich, das zuzugeben, {name}, aber diese Frostmanetrottel haben mich übers Ohr gehauen. Sie haben eine magische Rune gestohlen, die ich mir... ähm, aus der Schatzkammer \"geliehen\" habe. Ich dachte, das könnte mir sozusagen eine Starthilfe verschaffen, aber ich konnte sie nicht zum Funktionieren bringen.\n\nGeht in ihre Höhle im Süden und versucht, sie unter ihrer Beute zu finden, ja? Und dann versucht selbst Euer Glück mit der Rune. Ihr seht mir aus wie ein Bücherwurm. Nicht böse gemeint.", sourceObjective = "Holt die gestohlene Rune aus der Höhle der Frostmanetrolle im Coldridgetal. Setzt sie ein, um eine neue Fähigkeit zu lernen und kehrt zu Solm Hargrin in Anvilmar zurück.", completion = "Ihr habt flinke Finger, {name}. Seht diese Rune als ein Geschenk.\n\nWenn irgendjemand fragt, haben wir uns nie gesprochen, alles klar?", sourceObjectiveStatus = "unverified-source-field" }
quests[77660] = { id = 77660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erkundung der Höhlen", description = "Jäger sind ein rauer Haufen, {name}, sogar unter Zwergen. Wir reisen durch ganz Azeroth, um unerforschte Lande zu erkunden, und jagen alle mögliche gefährliche und exotische Beute. Auf Euren Reisen werdet Ihr Euch häufig allein in feindlichen Gebieten wiederfinden und müsst Euch zum Überleben auf Eure Gerissenheit verlassen.\n\nDie Frostmanetrolle haben eine mächtige Rune von uns gestohlen. Sie haben sie bestimmt in ihrer Höhle im Süden verstaut. Findet die Rune und nutzt sie, um eine neue Kampftechnik zu lernen. Kehrt zu mir zurück, wenn Ihr fertig seid.", sourceObjective = "Holt die gestohlene Rune aus der Höhle der Frostmanetrolle im Coldridgetal. Setzt die Rune ein, um eine neue Fähigkeit zu lernen und erstattet dann Thorgas Grimson in Anvilmar Bericht.", completion = "Gut gemacht, {name}. Die Anwendung der Rune auf Eure Ausrüstung wird Euch mächtige neue Fähigkeiten gewähren.\n\nEs gibt viele solcher Runen in ganz Azeroth. Sucht nach ihnen, sie werden Euch auf Eurer Reise eine gute Hilfe sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[77661] = { id = 77661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meditation über das Licht", description = "Das Licht hat mir Eure Zukunft gezeigt, {name}. Ich habe gesehen, wie Ihr gegen die Troggs im Südwesten kämpft. In einer Truhe werdet Ihr eine Erinnerung aus der Vergangenheit finden. Kehrt hierher zurück und kniet Euch vor den Altar des Lichts, sobald sie sich in Eurem Besitz befindet. Meditiert über ihre Geheimnisse.\n\nWenn Ihr Eure Gedanken gesammelt habt, wird diese Erinnerung für Euch Sinn ergeben und Ihr werdet eine neue Technik erlernen. Sprecht mit mir, wenn Ihr damit fertig seid.", sourceObjective = "Findet eine Erinnerung an die Vergangenheit in einer Truhe beim Trogglager in der Nähe von Anvilmar. Kniet Euch dann am Altar des Lichts in Anvilmar nieder und meditiert über das Licht. Benutzt die Erinnerung, um eine neue Fähigkeit zu erlernen. Sprecht danach mit Branstock Khalder.", completion = "Wenn das Licht Euch weitere Visionen offenbart, könnt Ihr jederzeit an heiligen Orten meditieren, um Eure Gedanken zu klären und über diese Geheimnisse nachzudenken.\n\nIch habe auch gesehen, dass Euer Weg Euch zu einem Gespräch mit unseren elfischen Verbündeten in Kalimdor führen wird. Mehr über ihre merkwürdigen Rituale der Mondanbetung zu erfahren, könnte uns von Nutzen sein, um auch ihnen eines Tages den Weg zum Licht zu zeigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[77666] = { id = 77666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestohlene Macht", description = "Ich habe mit einer neuen Art von Magie experimentiert, mit einer Rune, die Teufelsenergie kanalisieren kann, um mächtige Zauber zu wirken. Ich würde diese Macht mit Euch teilen, aber sie wurde mir von einem dieser lästigen Troggs gestohlen.\n\nIm Südwesten befindet sich ein Lager dieses Felsenkieferungeziefers. Seht nach, ob Ihr meine Rune irgendwo zwischen ihren Habseligkeiten findet, vermutlich ist sie in einer Art Truhe oder so. Meldet Euch wieder bei mir, sobald Ihr sie gefunden und ihre Magie gelernt habt. Es würde mir Freude bereiten zu sehen, dass mein Experiment genutzt wird.", sourceObjective = "Findet die Rune bei der Gruppe Troggs südwestlich von Anvilmar und benutzt sie, um eine neue Fähigkeit zu lernen. Kehrt danach zu Alamar Grimm in Anvilmar zurück.", progress = "Nun, {name}? Kommt Ihr voran?", completion = "Ihr scheint Euch gut an diese neue Magie gewöhnt zu haben, {name}. Findet mehr dieser Runen und prägt sie in Eure Ausrüstung. Setzt diese Macht gegen diejenigen ein, die sich Euch widersetzen.\n\nEines Tages wird Eure Macht vielleicht selbst die meinige übertreffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[77667] = { id = 77667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zauberforschung", description = "Als <Magier/Magierin> werden Euch die arkanen Forschungen zu außerordentlicher Macht führen. Die Notizen zu studieren, welche die größten Magier Azeroths hinterlassen haben, ist ein großartiger Anfang. Ich hatte vor Kurzem selbst einige entdeckt, aber sie wurden von diesen lästigen Troggs im Südwesten gestohlen.\n\nHolt die Zaubernotizen aus dem Trogglager und benutzt diese Fibel, um sie zu entziffern. Kehrt zurück, wenn Ihr Eure Untersuchung abgeschlossen habt.", sourceObjective = "Findet die gestohlenen Zaubernotizen im Trogglager südwestlich von Anvilmar und benutzt sie, um eine neue Fähigkeit zu lernen. Kehrt danach zu Marryk Nurribit in Anvilmar zurück.", progress = "Wie kommen Eure Forschungen voran, {name}?", completion = "Gut gemacht, {name}. Nehmt diese Verständnisamulette. Sie werden Euch dabei helfen, weitere arkane Schriften zu entziffern.\n\nSucht weiter nach Zaubernotizen in ganz Azeroth und nutzt sie, um Eure Forschung voranzubringen. Wenn Ihr mehr Amulette braucht, könnt Ihr diese bei einem Reagenzienverkäufer erwerben.", sourceObjectiveStatus = "unverified-source-field" }
quests[77668] = { id = 77668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlorene Rune", description = "Die Krieger der Dunklen Fürstin können Euch einiges beibringen, aber Ihr müsst auch selbst nach neuen Techniken suchen.\n\nEin anderer Krieger ist vor Kurzem in den Nachtwebergrund vorgedrungen. Er experimentierte damit, Runen in seine Ausrüstung zu prägen, um seine Kampffähigkeiten zu verbessern.\n\nIch vermute, dass er von den Spinnen überwältigt wurde, die sich in der Mine eingenistet haben. Findet die Rune in ihren Netzen und erlernt selbst diese Technik.", sourceObjective = "Findet die Rune, die im Nachtwebergrund verborgen liegt, und benutzt sie, um eine neue Technik zu lernen. Meldet Euch dann wieder bei Dannal Stern in Deathknell.", sourceObjectiveStatus = "unverified-source-field" }
quests[77669] = { id = 77669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die scharlachrote Rune", description = "Wer wart Ihr im Leben, {name}? <Ein Spion/Eine Spionin>? <Ein Dieb/Eine Diebin>? <Ein Koch/Eine Köchin>, <der/die> besonders geschickt mit dem Messer war? Wie auch immer Eure Vergangenheit aussieht, es ist an der Zeit, neue Taktiken zu entwickeln. Die Diebe der Verlassenen ergreifen jede Gelegenheit, die sich ihnen bietet.\n\nDie scharlachroten Konvertiten östlich von hier kämpfen, als hätten sie noch nie eine Schlacht gesehen, aber der Kreuzzug hat ihnen mystische Runen gegeben, um ihre Fähigkeiten zu verbessern. Stehlt eine dieser Runen und lernt ihre Magie. Kehrt dann zu mir zurück.", sourceObjective = "Bestehlt die scharlachroten Konvertiten oder tötet sie, um eine Rune zu finden, und benutzt sie, um eine neue Fähigkeit zu lernen. Kehrt danach zu David Trias in Deathknell zurück.", completion = "Gut gemacht, {name}. Die Anwendung der Rune auf Eure Ausrüstung wird Euch mächtige neue Fähigkeiten gewähren.\n\nEs gibt viele solcher Runen in ganz Azeroth. Sucht nach ihnen, sie werden Euch auf Eurer Reise eine gute Hilfe sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[77670] = { id = 77670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meditation über den Untod", description = "Ich werde in Euren Gedanken eine Erinnerung der Lebenden hervorrufen, vielleicht ist es sogar Eure eigene Erinnerung. Geht zum Friedhof neben der Kapelle und findet heraus, wo die Kälte des Todes am stärksten ist, dann kniet nieder und sammelt Eure Gedanken. Durch Konzentration auf die Geheimnisse des Untodes werdet Ihr Klarheit in dieser Erinnerung finden und eine neue Technik erlernen. Kehrt zu mir zurück, wenn Ihr damit fertig seid.", sourceObjective = "Kniet auf dem Friedhof nieder, um über den Untod zu meditieren, und benutzt dann die Rune, um eine neue Fähigkeit zu lernen. Kehrt danach zum Dunklen Kleriker Duesten in der Kapelle von Deathknell zurück.", completion = "Die Lebenden klammern sich aus einem Grund an das Licht: Sie fürchten in die Vergessenheit des Todes zu geraten. Als Verlassener hat diese Furcht keine Macht mehr über Euch. Obwohl das Licht nun sogar diejenigen unter uns zurückweist, die einst seine größten Verehrer waren, befehligen wir dunkle Mächte, die jenseits des Schattens des Todes liegen.\n\nWenn Ihr stärker werdet, empfehle ich Euch einige Zeit mit den Trollen der Horde zu verbringen. Obwohl ihre Kultur primitiv ist, haben die \"Loa\", die sie verehren, eine Verbindung zum Untod. Sie könnten Euch einen Einblick in unser Wesen verschaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[77671] = { id = 77671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zauberforschung", description = "Die Arkanisten der königlichen Apothekervereinigung widmen ihr Leben der Zauberforschung im Dienst der Verlassenen. Eure Berufung mag das Abenteuer sein, aber Ihr könnt der Dunklen Fürstin dienen, indem Ihr die Zaubernotizen, die Ihr auf Euren Reisen findet, sicherstellt und studiert.\n\nTötet die Initianden des Scharlachroten Kreuzzugs, die in der Nähe von Deathknell ihr Lager aufgeschlagen haben, und sammelt ihre Zaubernotizen. Benutzt die Fibel, um die Notizen zu entschlüsseln, und lernt einen neuen Zauber. Dann kehrt zu mir zurück.", sourceObjective = "Tötet Initianden des Scharlachroten Kreuzzugs, um Zaubernotizen zu finden, und benutzt diese, um einen neuen Zauber zu lernen. Kehrt dann zu Isabella in Deathknell zurück.", progress = "Was habt Ihr erfahren, {name}?", completion = "Gut gemacht, {name}. Nehmt diese Verständnisamulette. Sie werden Euch dabei helfen, weitere arkane Schriften zu entziffern.\n\nSucht weiter nach Zaubernotizen in ganz Azeroth und nutzt sie, um Eure Forschung voranzubringen. Wenn Ihr mehr Amulette braucht, könnt Ihr diese bei einem Reagenzienverkäufer erwerben.", sourceObjectiveStatus = "unverified-source-field" }
quests[77672] = { id = 77672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlorene Rune", description = "Ich habe mit einer neuen Art von Magie experimentiert, mit einer Rune, die Teufelsenergie kanalisieren kann, um mächtige Zauber zu wirken. Ich habe einen Lehrling ausgesandt, um die Rune an den Spinnen in der Mine im Norden auszuprobieren, aber er ist nicht zurückgekehrt. Ich vermute, wir werden ihn nicht wiedersehen.\n\nVielleicht werdet Ihr Euch als standhafter erweisen. Geht zur Mine und bergt die Rune aus den Spinnweben. Lernt ihre Magie und meldet Euch dann wieder bei mir.", sourceObjective = "Bergt die Rune aus dem Nachtwebergrund und benutzt sie, um eine neue Fähigkeit zu lernen. Kehrt dann zu Maximillion in Deathknell zurück.", completion = "Ihr scheint Euch gut an diese neue Magie gewöhnt zu haben, {name}. Findet mehr dieser Runen und prägt sie in Eure Ausrüstung, um neue Fähigkeiten gegen diejenigen einzusetzen, die sich Euch widersetzen.\n\nEines Tages wird Eure Macht vielleicht selbst die meinige übertreffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78088] = { id = 78088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein seltsames Artefakt", progress = "Habt Ihr in dem Turm etwas gefunden?", completion = "Ihr habt gut daran getan, das zu mir zu bringen, {name}." }
quests[78089] = { id = 78089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rat aus Stormwind", description = "Ich spüre eine dunkle Macht in dieser Kugel, aber ihre Quelle entzieht sich mir. Wir brauchen den Rat der Paladine von Stormwind. Bringt die Kugel zu ihnen.", sourceObjective = "Fragt die Paladine von Stormwind um Rat für die Kugel.", progress = "Bringt Ihr Neuigkeiten aus Kalimdor?", completion = "<Untersucht die Kugel mit beunruhigtem Gesichtsausdruck.>", sourceObjectiveStatus = "unverified-source-field" }
quests[78090] = { id = 78090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine zweite Meinung", description = "Ich bin mir nicht sicher, was diese Kugel beinhaltet, {name}. Ich denke, wir brauchen die Hilfe... eines Spezialisten.\n\nWir haben Kenntnis von einer Hexenmeistersekte, die aus Stormwind heraus operiert. Offiziell lehnen wir den Aufenthalt von Hexenmeistern in der Stadt ab. Inoffiziell kann ihr Wissen nützlich sein, wenn wir es mit dämonischen Kräften zu tun haben.\n\nFindet einen Abgesandten dieser Hexenmeister und fragt nach seiner Meinung zur Kugel.", sourceObjective = "Findet das Sanktum der Hexenmeister in Stormwind und bittet sie um Rat zur Kugel.", progress = "Ihr seid weit von der Kathedrale entfernt, {class}. Ich hoffe, es ist Euch bewusst, dass Ihr hier über keinerlei Befugnisse verfügt.", completion = "Die Silberne Hand benötigt also meine Hilfe? Das wird nicht billig.", sourceObjectiveStatus = "unverified-source-field" }
quests[78091] = { id = 78091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdient Euch Euer Salz", description = "Ich werde die Kugel untersuchen und Euch sagen, was ich herausfinde, aber zuerst müsst Ihr etwas für mich tun.\n\nDie Hexenmeister des Blackrockklans benutzen spezielle Salze, um ihre Beschwörungsrituale zu verstärken. Sammelt ein paar von den Orcs im Rotkammgebirge.\n\nWenn Ihr zurückkehrt, werde ich Euch die Ergebnisse meiner Untersuchungen mitteilen.", sourceObjective = "Sammelt 14 Beschwörersalze von den Beschwörern der Blackrock im Rotkammgebirge. Kehrt dann zu Ursula Deline in Stormwind zurück.", progress = "<Die Hexenmeisterin studiert die Kugel eindringlich.>", completion = "Ah... die Salze. Ich hatte sie ganz vergessen.\n\nDiese Kugel gleicht nichts, was ich zuvor gesehen habe, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[78092] = { id = 78092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie muss zerstört werden", description = "Diese Kugel ist in der Tat mit einer mächtigen Entität verbunden, irgendwo jenseits des Wirbelnden Nethers. Ich kann ihr Wesen nicht erahnen, aber ich fühle, wie ihre eigene Wahrnehmung durch die Kugel hindurch reicht... und mich ebenfalls studiert.\n\nIch gebe es nur ungern zu, {name}, aber die Kugel muss zerstört werden.\n\nSie scheint unempfindlich gegenüber den meisten Schadensarten zu sein, aber vielleicht kann die Waffe eines mächtigen Dämonenfürsten ihr etwas anhaben. Ich bin mir nicht sicher, wo Ihr eine solche Waffe finden könnt, aber es erscheint mir, Eure beste Möglichkeit zu sein.\n\nViel Glück, {name}.", sourceObjective = "Findet eine Möglichkeit, die Kugel zu zerstören.", progress = "<Euch stehen die Haare zu Berge, als teuflische Energien Euch umgeben.>", completion = "<Ihr hebt die Kugel in Richtung des Speers.>", sourceObjectiveStatus = "unverified-source-field" }
quests[78093] = { id = 78093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt zu Delgren zurück", description = "<Die geborstenen Reste der Kugel liegen vor Euren Füßen. Delgren wird sicher sehen wollen, was Euch gelungen ist.>", sourceObjective = "Bringt die Splitter der Kugel zu Delgren.", progress = "Habt Ihr einen Weg gefunden, die Kugel zu zerstören?", completion = "Das ist eine Erleichterung, {name}. Aber was immer Azeroth durch die Kugel hindurch beobachtet hat... Ich habe das Gefühl, es wird nicht sehr erfreut darüber sein, dass die Kugel zerstört wurde.\n\nNehmt dies als Dank für Eure Bemühungen. Und... seid vorsichtig.", sourceObjectiveStatus = "unverified-source-field" }
quests[78114] = { id = 78114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bändigung wilder Flügeldrachen", description = "Habt Ihr diese Prachtschwingenflügeldrachen gesehen, die hier herumfliegen? Ich würde darauf wetten, dass es den Leuten eine gute Stange Geld wert wäre, mir dabei zuzusehen, wie ich auf diesen Dingern einen Salto schlage!\n\nSie sind aber ein störrischer Haufen. Ich bring es nicht fertig, auf einem zu reiten, geschweige denn in luftiger Höhe einige Tricks durchzuführen.\n\nIch habe gehört, dass es möglich ist, einen speziellen Stab anzufertigen, um sie zu besänftigen. Wahrscheinlich könnte ich ihn sogar selbst herstellen. Alles, was ich dazu benötige, ist ein hypnotischer Kristall und ein knorriger Zauberstab der wilden Magie.\n\nNun bin ich mir nicht ganz sicher, wo es die gibt, aber wir können die Details später besprechen.", sourceObjective = "Bringt einen hypnotischen Kristall und einen knorrigen Zauberstab der wilden Magie zu Jixo Wahnrakete im Steinkrallengebirge.", progress = "Hattet Ihr Erfolg mit den Materialien?", completion = "Gut gemacht! Nun ist es an der Zeit für einen kleinen Feldversuch.", sourceObjectiveStatus = "unverified-source-field" }
quests[78121] = { id = 78121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen wilden Flügeldrachen bändigen", description = "Nun, da der Zauberstab hergestellt ist, gibt es nur noch eine Sache zu erledigen. Ich werde selbst einen Flügeldrachen zähmen!\n\nIhr solltet mitkommen, {name}. Ihr werdet für mein neuestes Kunststück einen Platz in erster Reihe haben!", sourceObjective = "Folgt Jixo Wahnrakete und seht zu, wie er einen Flügeldrachen zähmt.", completion = "Lasst mich Euch sagen, {name}, dieser Sturz war noch schmerzhafter, als er ausgesehen hat. Das wird schon wieder, aber ich glaube nicht, dass der alte Jixo in der Zukunft noch Flügeldrachen bändigen wird.\n\nVielleicht sollte ich einfach beim Altbewährten bleiben, wisst Ihr? Stunts, wie mit einem Chopper über zwanzig aufgereihte Gnome springen. Auf sowas stehen die Leute.\n\nNehmt den Zauberstab. Ich habe keine Verwendung mehr dafür. Und hier ist noch ein kleiner Bonus für die ganzen Unannehmlichkeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[78124] = { id = 78124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Almanach von Nar'thalas", progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, {name}. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte." }
quests[78127] = { id = 78127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dalaranauswahl", progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, {name}. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte." }
quests[78132] = { id = 78132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helm des Drachentöters", progress = "Der Helm des Drachentöters gehörte einst einem großen Kommandanten, der im Kampf fiel. Es heißt, seine gepeinigte Seele würde noch immer am Ort seines Ablebens umhergeistern.", completion = "Ausgezeichnete Arbeit, {name}! Damit bin ich auf meinem Weg zu Ruhm und Ehre einen Schritt weiter." }
quests[78133] = { id = 78133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schild des Drachentöters", progress = "Gerüchten zufolge befindet sich der Schild des Drachentöters im Besitz eines orcischen Kriegsfürsten. Er nahm ihn während eines Überfalls auf eine Menschensiedlung an sich.", completion = "Ausgezeichnete Arbeit, {name}! Damit bin ich auf meinem Weg zu Ruhm und Ehre einen Schritt weiter." }
quests[78134] = { id = 78134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lanze des Drachentöters", progress = "Die Lanze des Drachentöters hat mehrmals den Besitzer gewechselt. Von Zeit zu Zeit sprechen Gerüchte davon, sie auf einem Schwarzmarkt gesehen zu haben. Vielleicht ist der derzeitige widerwärtige Eigentümer bereit, sich von ihr zu trennen... gegen Bezahlung.", completion = "Ausgezeichnete Arbeit, {name}! Damit bin ich auf meinem Weg zu Ruhm und Ehre einen Schritt weiter." }
quests[78142] = { id = 78142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Betörungen und Verzauberungen", progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, {name}. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte." }
quests[78143] = { id = 78143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse der Träumer", progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, {name}. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte." }
quests[78144] = { id = 78144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alonso der Drachenschlächter", description = "Die Zeit ist gekommen, {name}. Ich trage die Rüstung, die einem wahren Drachentöter zusteht! Ihr wart mir eine große Hilfe.\n\nIch sollte Euch anbieten, mich als <mein Ehrenknappe/meine Ehrengehilfin> zu begleiten und mir dabei zuzusehen, wie ich den großen Drachen ein für alle Mal niederstrecke.", sourceObjective = "Begleitet Alonso, um den Drachen niederzustrecken.", completion = "Ich habe es geschafft, {name}! Endlich ist mein Gegner besiegt!\n\nOh, der Klang von Fangzahn auf Metall, von Schuppe auf Klinge. Welch Gefahr, welch Nervenkitzel! Und nach all dem erhebe ich mich als Champion.\n\nUnd lasst uns nicht Euren bescheidenen Beitrag vergessen! Ohne die Rüstung, die Ihr mir gebracht habt, hätte ich das Ungeheuer sicher niemals bezwingen können.\n\nIhr habt Euch als exzellenter Knappe erwiesen, {name}. Vielleicht werdet auch Ihr eines Tages auf dem glorreichen Pfad des Ritters wandeln.", sourceObjectiveStatus = "unverified-source-field" }
