quests[78150] = { id = 78150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freund der Bibliothek", sourceObjective = "Dank Eurer Spenden entwickelt sich die Bibliothek prächtig.\n\nBitte, nehmt das.", sourceObjectiveStatus = "unverified-source-field" }
quests[78192] = { id = 78192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse des Lichts", description = "Ihr wollt also mehr über das Licht erfahren? Dann seid Ihr bei mir genau richtig! Ich bringe Heilung, Pein UND Schutz!\n\nWie wäre es mit einer kleinen Übung? Begebt Euch nach Ashenvale und zeigt einem dieser Hordenzombies, die denken, ihnen würde alles gehören, was eine Harke ist. Das Licht ist für vieles gut, aber Untoten Feuer unterm Hintern machen ist mein Liebling!", sourceObjective = "Tötet 7 Kräuterkundige der Verlassenen und 9 Sucher der Verlassenen im Nordwesten Ashenvales und kehrt dann zu Maethra Schlackherz in Darnassus zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[78193] = { id = 78193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse des Lichts", description = "Also gut, {name}, seien wir mal für einen Augenblick ernst. Das Licht ist nicht irgendeine Göttin, die es zu beeindrucken gilt, oder ein Geist, dem man die Freundschaft anbietet. Es ist in uns allen! Man muss nur lernen, es zu fühlen.\n\nBelohnt Euch mit einer Reise nach Stormwind und besucht die Kathedrale des Lichts. Ein wunderbarer Ort, um zu beten und um sich mit dem Licht vertraut zu machen. Und die Architektur ist ein wahrer Augenschmaus!", sourceObjective = "Reist nach Stormwind und sprecht mit Hohepriesterin Laurena in der Kathedrale des Lichts.", sourceObjectiveStatus = "unverified-source-field" }
quests[78194] = { id = 78194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse von Elune", description = "Es tut gut, zu sehen, dass Euresgleichen sich für Elune interessiert. Obschon die Kaldorei ihre liebsten Kinder sind, sorgt sie sich doch um alle Völker Azeroths. Im Gegenzug für ihre Segnungen kümmern wir uns in ihrem Namen um das Land.\n\nKürzlich hat man mich auf Störungen im Gleichgewicht der Natur hingewiesen: tollwütige Terrorwölfe, die im Dämmerwald gesichtet wurden. Zollt Elunes Gleichgewicht Respekt, indem Ihr ihre Zahl dezimiert, und kehrt dann mit Beweisen Eurer Taten zu mir zurück.", sourceObjective = "Sammelt 10 Terrorwolftatzen von Wölfen im Dämmerwald.", progress = "Was für Neuigkeiten bringt Ihr mir?", completion = "Ich danke Euch, {name}. Dank Eurer Anstrengungen ist das Gleichgewicht stärker.", sourceObjectiveStatus = "unverified-source-field" }
quests[78195] = { id = 78195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse von Elune", description = "Die Mondbrunnen enthalten Elunes Segen, aber sie sind auch ein Symbol der Verbindungen, die wir alle teilen. Bringt diese Phiole mit Wasser aus Stormwinds Mondbrunnen zu dem in Auberdine, an der Küste Kalimdors. Wenn sich die Wasser verbinden, verbindet sich auch Euer Geist mit dem der Kaldorei.", sourceObjective = "Bringt die Phiole zu Syrnoya beim Mondbrunnen von Auberdine.", sourceObjectiveStatus = "unverified-source-field" }
quests[78196] = { id = 78196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse des Untodes", description = "Wenn Ihr Glaube oder Huldigung unter den Priestern der Verlassenen sucht, so werdet Ihr enttäuscht werden. Wir haben über den Tod hinausgeblickt und wir wissen, dass uns dort nichts erwartet. Unsere Religiosität entspringt eiskalter Erfahrung, nicht naiver Hoffnung.\n\nErfahrung... Das ist es, was Ihr braucht. Sammelt Schattenblätter von den Sumpfwesen in Ashenvale und kehrt dann zu mir zurück. Ich habe eine Idee, die Eure Fragen beantworten könnte.", sourceObjective = "Sammelt 12 Schattenblätter von Schattendickichtelementaren in Ashenvale.", sourceObjectiveStatus = "unverified-source-field" }
quests[78197] = { id = 78197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse des Untodes", description = "Alle Verlassenen haben einmal am Rande des Todes gestanden. Zu erleben, wie die Existenz endet, ohne Götter auf der anderen Seite... das mag sich furchterregend anhören, aber in Wahrheit ist es befreiend. Unser Wille gehört uns und ist keinen Mächten verpflichtet außer uns selbst.\n\nBegebt Euch zum Friedhof von Brill und trinkt diese Tinktur. Sie wird Euch an den Rand des Todes bringen und Euch dort halten. Stellt Euch dem Vergessen mit Entschlossenheit und Ihr werdet einen Weg zurück zu den Lebenden finden. Mir fällt kein besserer Weg ein, um mit Euch zu teilen, was es bedeutet, ein Verlassener zu sein.", sourceObjective = "Reist zum Friedhof von Brill in Tirisfal und benutzt die Tinktur des Wachtods.", sourceObjectiveStatus = "unverified-source-field" }
quests[78198] = { id = 78198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse der Loa", description = "Die mächtigen Trollreiche unserer Vorfahren wurden erbaut auf der Stärke der Loa, Geister mit großer Macht, die Azeroth beherrschen. Wir verehren viele Loa im Darkspearstamm, aber wenn Ihr interessiert daran seid, unseren Glauben zu teilen, dann gibt es einen, der bereit sein könnte, mit Euch zu handeln.\n\nZuerst müsst Ihr eine Opfergabe vorbereiten. Reist nach Tarrens Mühle und greift die Menschen an, die sich dem Anspruch der Horde auf das Gebiet widersetzen. Sammelt die Knochen Eurer Opfer und kehrt zu mir zurück.", sourceObjective = "Sammelt 14 menschliche Knochen von Hillsbrad von Menschen des Vorgebirges von Hillsbrad, kehrt dann zu Baj'ura in Undercity zurück.", progress = "Wie läuft Euer Kampf gegen die Menschen?", completion = "Ausgezeichnet... Die eignen sich für eine gute Opfergabe.", sourceObjectiveStatus = "unverified-source-field" }
quests[78199] = { id = 78199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse der Loa", description = "Bringt die Opfergabe in den Süden, zu den Echoinseln. An den Stränden werdet Ihr einen Schrein finden, der Bwonsamdi, dem Loa des Todes, geweiht ist. Ein Opfer eines Verlassenen wird zweifelslos seine Aufmerksamkeit auf sich ziehen.\n\nIch muss Euch aber warnen, {name}. Der Handel mit einem Loa fordert immer einen Preis. Es mag sein, dass Ihr noch nicht wisst, was Ihr aufgebt, aber Bwonsamdi treibt letztendlich immer seine Schulden ein.", sourceObjective = "Reist zu den Echoinseln und setzt die Opfergabe bei Bwonsamdis Schrein ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[78229] = { id = 78229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prüfung der Eulen", description = "Lasst mich das Symbol sehen, das Ihr da habt, {name}.\n\nEs scheint, als hättet Ihr mit der Prüfung der Eulen begonnen. Dies markiert einen Schlüsselmoment auf Eurem Weg als Druide.\n\nEs gibt weitere Symbole wie dieses, zu finden sind sie in ganz Azeroth. Um sie zu verdienen, müsst Ihr Meisterleistungen mit Geist und Körper vollbringen.\n\nEine Eule sitzt unter einem großen Baum in den Östlichen Königreichen. Eine weitere befindet sich in der Nähe eines großen Baums hier in Kalimdor. Und eine letzte ist dem Wasser zugeneigt und wartet in der Nähe der Küste von Hillsbrad.\n\nBegebt Euch zu diesen Eulen, {name}, und bringt mir ihre Symbole.", sourceObjective = "Bringt die Symbole der drei Eulen zu Loganaar in Moonglade.", progress = "Wie kommt Ihr voran mit der Prüfung, {name}?", completion = "Ich möchte Euch gratulieren, {name}. Was Ihr vollbracht habt, ist keine Kleinigkeit.\n\nDas Bestehen der Prüfung der Eulen beweist die Einstimmung auf alle Aspekte Eurer druidischen Bestimmung.\n\nNehmt diese Rune als Zeichen Eures Triumphs. Ich hoffe, es wird Euch gute Dienste leisten bei Eurer Aufgabe als Wächter des Smaragdgrünen Traums.", sourceObjectiveStatus = "unverified-source-field" }
quests[78261] = { id = 78261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Horn von Xelthos", description = "<Ein Zettel liegt in der Kiste>\n\nIch grüße Euch, {name}.\n\nIch begehre einen Schatz, bekannt als Horn von Xelthos, der sich irgendwo in der Burg Shadowfang befindet.\n\nNormalerweise fordert ein Besuch dieser Burg Verstärkung. Für diesen Auftrag ist es jedoch äußerst wichtig, dass so wenige wie möglich davon wissen.\n\nIhr müsst ihn alleine erledigen.\n\nIch habe einen Kontakt namens Veenix, der sich im Steinkrallengebirge aufhält. Er sollte in der Lage sein, Euch am Tor des Hofes vorbeizuschmuggeln. Von da an seid Ihr auf Euch gestellt.\n\nBringt das Horn hierher zurück, und die Bezahlung wird bald danach an Euch gehen.\n\n- C", sourceObjective = "Findet das Horn von Xelthos in der Burg Schattenfang. Kehrt dann zum toten Briefkasten von C bei Pyrewood zurück. Diesen Auftrag müsst Ihr alleine erledigen.", progress = "<Die Kiste ist leer.>", completion = "<Ihr platziert das Horn von Xelthos in der Kiste>", sourceObjectiveStatus = "unverified-source-field" }
quests[78265] = { id = 78265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fischöl", progress = "Ich werde Fischöl brauchen - und zwar eine ganze Menge davon!", completion = "Vielen Dank, {name}. Ich weiß das gut einzusetzen." }
quests[78266] = { id = 78266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verordnung der Dunkeleisenzwerge", progress = "Ich brauche eine Verordnung der Dunkeleisenzwerge. Wo man Dunkeleisenzwerge findet? Das ist Euer Problem!", completion = "Vielen Dank, {name}. Ich weiß das gut einzusetzen." }
quests[78267] = { id = 78267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schredderturbolader", progress = "Ich brauche ein paar der Schredderturbolader der Venture Company. Sie sind fest mit den Schreddersystemen verbunden, Ihr werdet also Spezialausrüstung brauchen, um sie zu bergen.\n\nNein, von mir bekommt Ihr diese Ausrüstung nicht.", completion = "Vielen Dank, {name}. Ich weiß das gut einzusetzen." }
quests[78270] = { id = 78270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goblinischer Schlossknacker", description = "<Ein Zettel liegt in der Kiste>\n\nIch grüße Euch erneut, {name}.\n\nIch begehre einen Schatz, bekannt als Horn von Xelthos, der sich irgendwo in der Burg Schattenfang befindet.\n\nNormalerweise fordert ein Besuch dieser Burg Verstärkung. Für diesen Auftrag ist es jedoch äußerst wichtig, dass so wenige wie möglich davon wissen.\n\nIhr müsst ihn alleine erledigen.\n\nIch habe einen Kontakt namens Veenix, der sich im Steinkrallengebirge aufhält. Er sollte in der Lage sein, Euch am Tor des Hofes vorbeizuschmuggeln. Von da an seid Ihr auf Euch gestellt.\n\nBringt das Horn hierher zurück, und die Bezahlung wird bald danach an Euch gehen.\n\n- C", sourceObjective = "Findet das Horn von Xelthos in der Burg Schattenfang. Kehrt dann zum toten Briefkasten von C bei Pyrewood zurück.", progress = "Ihr sagt, Ihr wollt in die Burg Schattenfang... alleine? Ihr habt Mumm!\n\nIch kann Euch Sprengstoff besorgen, um Euch auf die andere Seite des Tors zu bringen, aber ich brauche einen Arbeitsauftrag, damit ich das einigermaßen korrekt verbuchen kann. Einer der Angestellten hier sollte einen dabei haben. Vermutlich einer, der an irgendwas tüftelt oder baut.", completion = "Gut gemacht, {name}. Ich schätze, das war ein Kinderspiel für jemanden wie Euch.\n\nWie versprochen, hier ist, was Ihr benötigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[78277] = { id = 78277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Zeichen der Dankbarkeit", sourceObjective = "Es mag töricht gewesen sein, aber Thule, Gunther und ich waren wie eine Familie... wie Brüder. Wir haben niemals erwartet, dass unsere Welt in Stücke gerissen würde oder dass Thule sich auf die Seite des Lichkönigs schlagen würde. Und dass Gunthar und ich um unsere Menschlichkeit würden kämpfen müssen...\n\nIch kann spüren, wie der Makel der Geißel in Thules Teil des Zauberstabs hineinsickert. Er wird für immer ruiniert sein, korrumpiert durch seinen Verrat, aber ich bin nicht bereit, loszulassen... Vielleicht irgendwann.\n\nBitte, akzeptiert dieses Symbol des Wissens als meinen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[78287] = { id = 78287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich habe ein Angebot für Euch", description = "Es ist alles zusammengepackt, {name}. Bringt dies nach Stormwind und zeigt es einem der höheren Tiere dort. Jemandem, der heute noch unterschreiben kann!", sourceObjective = "Bringt Meister Holz in Stormwind die Waffenlieferung.", progress = "Eine Lieferung aus Ratschet? Ich habe nichts aus Ratschet bestellt.", completion = "Ein Waffenlieferant in Ratchet? Nun... die Allianz braucht alle Vorräte, die sie bekommen kann. Und wir wollen nicht, dass die Horde einen Vertrag unterzeichnet. Wir sollten schnell handeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[78288] = { id = 78288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich habe ein Angebot für Euch", description = "Es ist alles zusammengepackt, {name}. Bringt dies nach Orgrimmar und zeigt es einem der höheren Tiere dort. Jemandem, der heute noch unterschreiben kann!", sourceObjective = "Bringt Zel'mak in Orgrimmar die Waffenlieferung.", progress = "Eine Lieferung aus Ratschet? Ich habe nichts aus Ratschet bestellt.", completion = "Ein Waffenlieferant in Ratchet? Hmm... die Horde versucht seit geraumer Zeit, Geschäfte mit den Goblins weg von der Allianz und stattdessen zu uns zu leiten. Wir sollten schnell handeln und uns diese neue Gelegenheit sichern.", sourceObjectiveStatus = "unverified-source-field" }
quests[78297] = { id = 78297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vertragsabschluss", description = "Ich habe an den entsprechenden Stellen unterschrieben, {name}. Bringt das zurück nach Ratchet und erklärt dem Lieferanten, dass die Allianz sich darüber freut, Geschäfte mit ihm zu machen.", sourceObjective = "Kehrt mit dem unterschriebenen Beschaffungsvertrag zu Grizzby in Ratschet zurück.", progress = "Habt Ihr den Handel abgeschlossen?", completion = "Sie haben unterschrieben ohne zu verhandeln? Ha! Läuft für den guten alten Grizzby!\n\nUnd Ihr, {name}, Ihr habt Euch als Goldstück erwiesen. Hier, bitte, ein kleines Zeichen meiner Dankbarkeit.\n\nUnd da wir nun offiziell Geschäftspartner sind, schaut Euch ruhig ein bisschen um und lasst mich wissen, wenn Euch etwas anlacht. Ich gebe Euch sogar einen Mitarbeiterrabatt!", sourceObjectiveStatus = "unverified-source-field" }
quests[78304] = { id = 78304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vertragsabschluss", description = "Ich habe den Vertrag unterschrieben und versiegelt, {name}. Sagt diesem Goblin, dass er ab sofort ausschließlich mit der Horde zu tun hat.", sourceObjective = "Kehrt mit dem unterschriebenen Beschaffungsvertrag zu Grizzby in Ratschet zurück.", progress = "Habt Ihr den Handel abgeschlossen?", completion = "Sie haben unterschrieben ohne zu verhandeln? Ha! Läuft für den guten alten Grizzby!\n\nUnd Ihr, {name}, Ihr habt Euch als Goldstück erwiesen. Hier, bitte, ein kleines Zeichen meiner Dankbarkeit.\n\nUnd da wir nun offiziell Geschäftspartner sind, schaut Euch ruhig ein bisschen um und lasst mich wissen, wenn Euch etwas anlacht. Ich gebe Euch sogar einen Mitarbeiterrabatt!", sourceObjectiveStatus = "unverified-source-field" }
quests[78307] = { id = 78307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Horn von Xelthos", description = "Beschreibung", completion = "<Ein Zettel liegt in der Kiste>\n\nFür {name}. Wir sehen uns.\n\n- C" }
quests[78506] = { id = 78506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementare Not", description = "Hört zu, {name}. Die Korruption, von der ich zuvor gesprochen habe, betrifft mehr als nur Baron Aquanis. Ich spüre schon seit geraumer Zeit eine gewisse Unruhe in der Welt der Elementare. Ich fürchte, dass etwas im Argen liegt, und die Korruption von Baron Aquanis bestätigt lediglich meine Vermutungen.\n\nFindet hier im Eschental und dem Steinkrallengebirge in der Nähe mehr von diesen leidenden Elementaren. Bringt mir Partikel ihrer Essenz. Vielleicht kann ich sie analysieren und dadurch langsam verstehen, worin ihr Zorn gründet.", sourceObjective = "Sammelt Partikel elementaren Zorns und bringt sie zu Je'neu Sancrea beim Außenposten von Zoram'gar im Eschental.", sourceObjectiveStatus = "unverified-source-field" }
quests[78537] = { id = 78537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixier der Einsicht", description = "Die Partikel, die Ihr gesammelt habt, sind ein bedeutender Hinweis, {name}, doch wir werden etwas spirituelle Weisung benötigen, wenn wir die Situation komplett verstehen wollen.\n\nEs gibt ein Ritual, das ich häufig durchführe, für das ein Elixier der Einsicht benötigt wird. Die Visionen, die es gewährt, werden uns den weiteren Weg aufzeigen, den wir gehen müssen.\n\nIch kann das Elixier aus zwei anderen Elixieren brauen. Ein Elixier der Wasseratmung, um den Körper zu befreien, und ein Elixier der Weisheit, um den Geist zu öffnen.\n\nBringt sie mir, dann können wir mit dem Ritual beginnen.", sourceObjective = "Bringt ein Elixier der Wasseratmung und ein Elixier der Weisheit zu Je'neu Sancrea beim Außenposten von Zoram'gar in Eschental.", sourceObjectiveStatus = "unverified-source-field" }
quests[78561] = { id = 78561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixier der Einsicht", description = "Das Elixier ist bereit, {name}. Geht runter zum Freudenfeuer am Strand und trinkt davon. Vernehmt die Vision, die die Geister Euch offenbaren, und kehrt dann mit Euren Erkenntnissen zurück zu mir.", sourceObjective = "Trinkt das Elixier der Einsicht in der Nähe des Freudenfeuers am Außenposten von Zoram'gar und werdet Zeuge der Vision, die es Euch offenbart.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[78575] = { id = 78575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hirzek", description = "Der Stacheleber, den Ihr in Eurer Vision gesehen habt. Ich glaube, das war Hirzek.\n\nDer Irdene Ring weiß schon seit geraumer Zeit von der vulgären Variante des Schamanismus der Stacheleber. Es gibt jedoch Gerüchte, dass einige von ihnen vor Kurzem beunruhigende Fortschritte erzielt haben. Hirzek ist einer dieser Stacheleber.\n\nVon dem, was Ihr gesehen habt, können wir schließen, dass er Elementare versklavt, statt mit ihnen zusammenzuarbeiten, wie wir beide es tun würden. Das sorgt auf der Ebene der Elementare zweifelsohne für Aufruhr.\n\nIhr müsst ihn aufhalten, {name}. Zum Wohle der Schamanen und Elementare gleichermaßen.", sourceObjective = "Tötet Hirzek im Schwarzdorngrat im Brachland und bringt seinen Stab zu Je'neu Sancrea beim Außenposten von Zoram'gar im Eschental.", progress = "Hirzeks Taten sind eine Beleidigung gegenüber den schamanistischen Bräuchen und den Elementen selbst. Er muss aufgehalten werden.", completion = "<Je'neu nimmt den Stab in seine Hände.>\n\nDas war eine große Tat von Euch, {name}. Ich bin erleichtert, zu wissen, dass Hirzeks Quälereien ein Ende gefunden haben. Ich fürchte jedoch, dass er lediglich symptomatisch für eine größere Krankheit war. Es gibt noch viele weitere Elementare in Azeroth, die vor Pein nach Hilfe schreien.\n\nEs bleiben viele Fragen, die es zu beantworten gilt. Vermutlich sogar mehr, als zu Beginn unseres Unterfangens. So oder so, ich danke Euch für die Dienste, die Ihr dem Irdenen Ring erbracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[78611] = { id = 78611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine abgefangene Lieferung", sourceObjective = "Bei dieser Lieferung fehlen einige Gegenstände, aber sie wird sich dennoch als nützlich erweisen. Vielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[78612] = { id = 78612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine komplette Lieferung", progress = "Habt Ihr etwas für mich?", completion = "Es ist alles da! Vielen Dank, {name}. Diese Vorräte sind an vorderster Front unentbehrlich." }
quests[78676] = { id = 78676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge von Bhossca", description = "<Eine Notiz liegt in der Truhe.>\n\nIch bin froh, dass Ihr zurück seid, {name}.\n\nDas neueste Objekt meines Begehrens ist ein Artefakt, das als das Auge von Bhossca bekannt ist. Meine Quellen deuten darauf hin, dass das Auge irgendwo im Scharlachroten Kloster verborgen liegt. Wie bei Burg Shadowfang müsst Ihr Euch auch alleine in das Kloster schleichen.\n\nMöglicherweise müsst Ihr Euch eine Verkleidung suchen, bevor Ihr hineingeht. Damit kommt Ihr Euch etwas einfacher bewegen. Ich bin sicher, Ihr könnt etwas auf dem Klostergelände finden.\n\nBringt das Auge hierher und Eure Bezahlung wird wie gewohnt geliefert.\n\n- C", sourceObjective = "Findet das Auge von Bhossca im Scharlachroten Kloster. Kehrt dann zum toten Briefkasten von C bei Pyrewood zurück. Diesen Auftrag müsst Ihr alleine erledigen.", progress = "<Die Kiste ist leer.>", completion = "<Ihr legt das Auge von Bhossca in die Truhe.>", sourceObjectiveStatus = "unverified-source-field" }
quests[78680] = { id = 78680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerüchten zufolge", description = "In den Schatten wird von einer Waffe gemunkelt, die die Seele eines mächtigen dämonischen Wesens enthält. Niedere Dämonen wie Soran'ruk sind eine Sache, doch deutlich mächtigere Entitäten, die als Bestrafung für ihr Verfehlen gebunden wurden, können unvorstellbare Macht bieten.\n\nDiese Waffe ging vor Ewigkeiten verloren. Zerschmettert während des Dritten Kriegs.\n\nNeuerdings sprechen die Gerüchte von Magiern, die sich mit dunkler Magie jenseits ihres Verständnisses einlassen und Fragmente der Waffe geborgen haben sollen. Sie sollen jedoch nicht in der Lage sein, die Mächte im Inneren freizusetzen, ohne die Waffe wiederherzustellen.", sourceObjective = "Über die Aufenthaltsorte dieser zertrümmerten Waffenfragmente ist nur wenig bekannt. Nur, dass die beiden Fragmente im Besitz einst großer Magier in bedeutsamen Türmen aufbewahrt werden sollen. Einer soll sich nördlich von hier auf Kalimdor und der andere soll sich nahe des Herzens der Östliche Königreiche befinden.\n\nSeht, ob die Gerüchte wahr sind... Sucht nach den beiden vermissten Hälften der Waffe und bringt sie zu mir.", progress = "Immer noch keine Spur von den Waffenfragmenten? Ich schätze, ich habe Euch vergeblich losgeschickt.", completion = "Es gibt noch einiges zu tun, bevor ich eine Waffe dieser Macht wiederherstellen kann. Wir haben uns auf diesen Pfad begeben und nun gibt es kein Zurück mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[78681] = { id = 78681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Beschwörung", description = "Der Dämon, Des'Altek, scheint aus seinem Gefängnis ausgebrochen zu sein, doch er ist nach wie vor daran gebunden, wie ein Gefangener an seine Zelle. Wir müssen den Dämon beschwören, um seine Seele erneut einzufangen.\n\nWeiter nördlich, in Ashenvale, wo große Dämonen einst fielen, gibt es einen Ort am Kamm, den die Legion einst für Opferungen genutzt hat. Der Boden ist von den grauenhaften Ereignissen, die sich dort zugetragen haben, dauerhaft gebrandmarkt. Doch wenn wir von den Dämonen, die dieses Land nach wie vor plagen, das Blut der Legion zusammentragen können... das wäre der Schlüssel.", sourceObjective = "Sammelt 10 Einheiten Blut der Legion und führt das Ritual durch, um Des'Altek zu beschwören und dessen Seele erneut einzufangen.", progress = "Reicht eine Opfergabe des Blutes dar.", completion = "Benutzt den dunklen Ritualstein, um das dunkle Ritual zu beginnen. Jetzt gibt es kein Zurück...", sourceObjectiveStatus = "unverified-source-field" }
quests[78684] = { id = 78684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisvoller Reisender", description = "Was? Wo bin ich? Wie... bin ich hierhergekommen?\n\n<Der Mann vor Euch stolpert herum, als wäre er seekrank. Seine Augen weiten sich und seine Hände zittern, als Ihr Euch für einen Moment gegenseitig verwirrt anstarrt.>\n\nAh... <ein Hexenmeister/eine Hexenmeisterin>, wie ich sehe. Vieleicht besprechen wir, wie es zu dieser Reihe an Ereignissen kam, und möglicherweise finden wir heraus, was schiefgelaufen ist?\n\n<Unsicher, was Ihr als Nächstes tun sollt, schlagt Ihr vor, mit Doan Karhan zu sprechen.>", sourceObjective = "Trefft Euch mit Doan Karhan und dem geheimnisvollen Reisenden im Brachland.", completion = "Interessant, in der Tat... Ich habe Euch losgeschickt, um einen Dämon zu töten, ich hätte im Leben nicht gedacht, dass Ihr mit einem Freund zurückkehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[78699] = { id = 78699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge von Bhossca", description = "Beschreibung", completion = "<Ein Zettel liegt in der Kiste>\n\nFür {name}. Ich halte ein \"Auge\" nach Euch offen.\n\n- C" }
quests[78702] = { id = 78702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raszel Ander", sourceObjective = "Raszel war ein Freund... einer, von dem ich dachte, ich hätte ihn vor langer Zeit verloren... Damals waren wir junge Lehrlinge... Vieles hat sich geändert.\n\nDer Ausgang des Rituals mag ein Rückschlag gewesen sein, aber ich glaube, wir können die Waffe immer noch rekonstruieren.\n\nRaszel und ich haben viel zu besprechen, gemeinsam werden wir einen Plan schmieden. Ich lasse nach Euch schicken, wenn wir wissen, wie wir weitermachen.\n\nIn der Zwischenzeit, nehmt das. Ich glaube, Ihr könntet daran interessiert sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[78823] = { id = 78823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrecken des Wüstenhimmels", description = "Die Zeichnung besteht aus groben, breiten Strichen und schient einen großen Raubvogel darzustellen. Trotz der einfachen Darstellung hat der Künstler diese Kreatur eindeutig mir Furcht und Bewunderung betrachtet. Ein Experte für Großwild könnte Euch bestimmt mehr verraten.", sourceObjective = "Bring die einfache Zeichnung zu Hemet Nesingwary im Schlingendorntal.", completion = "Aber hallo. Das ist mal interessant...", sourceObjectiveStatus = "unverified-source-field" }
quests[78830] = { id = 78830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrecken des Wüstenhimmels", description = "Diese Zeichnung erinnert mich an eine Geschichte, die ich auf einer anderen Expedition vor nicht allzu langer Zeit gehört habe. Man erzählte mir von einem großen Vogel, Gharrik, der als Alpharaubtier über die Ödlande herrscht.\n\nEr wurde zuletzt nordöstlich von Camp Cagg gesehen. Vielleicht ist sein Nest irgendwo in der Nähe?\n\nIhr werdet Lebendköder brauchen, wenn Ihr ihn hervorlocken wollt. Ich werde Euch einen Käfig leihen, um welchen zu fangen. Kleine Wildtiere sind im Ödland selten, ihr werdet Euren Köder also anderswo suchen müssen.\n\nEine Feder von Gharrik wäre eine gute Trophäe. Man würde sich sicherlich Geschichten von Euch im Lager erzählen.", sourceObjective = "Holt Euch eine blutrote Trophäenfeder von Gharrik im Ödland. Kehrt anschließend zu Hemet Nesingwary im Schlingendorntal zurück.", progress = "Wie läuft die Jagd? Der Vogel hat Euch doch sicher nicht überlistet!", completion = "Jetzt habt Ihr eine Feder für Eure Kappe! Gut gemacht, {name}.\n\nIhr könnt Euch hier eine Weile ausruhen, wenn Ihr wollt. Ich bin sicher, Eure Wanderung durch die Wüste war beschwerlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[78872] = { id = 78872, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine komplette Lieferung", progress = "Habt Ihr etwas für mich?", completion = "Es ist alles da! Vielen Dank, {name}. Diese Vorräte sind an vorderster Front unentbehrlich." }
quests[78909] = { id = 78909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veränderlicher Schuppentalisman", description = "Ich brauche eine... erhebliche Menge Materialien für den Talisman.\n\n<N'ora lächelt euch verschlagen an>", sourceObjective = "Bringt N'ora Jederherz die folgenden Materialien und eine Handvoll veränderliche Schuppen, um den Talisman fertigzustellen: 1 Beutel mit seltsamem Staub, 5 große Magieessenzen, 2 kleine gleißende Splitter und 5 Goldstücke.", progress = "Ich gebe zu, dass ich mich nicht besonders gut in Verzauberkunst auskenne, aber ich glaube, ich verstehe ungefähr, wie der Prozess funktioniert. In der Theorie zumindest.", completion = "Ich wünsche Euch alles Gute auf Euren Abenteuern und hoffe, Ihr findet den Weg zu mir zurück, solltet Ihr weitere wundersame Entdeckungen wie diese machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[78914] = { id = 78914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seelengefäß", description = "Gobliningenieure haben versucht, einen synthetischen Seelenstein herzustellen, aber ihre Methoden waren plump, gelinde gesprochen. Doch trotz ihrer Fehler sind sie auf der richtigen Spur.\n\nIch habe gehört, dass die Goblins einer Fraktion von Händlern die Rechte für das Rezept abgeluchst haben. Es ist unwahrscheinlich, dass sie wissen, dass das Seelengefäß an sich keine magischen Kräfte birgt. Jemand will das Muster bestimmt gegen einige Münzen loswerden wollen.", sourceObjective = "Jetzt, da wir einen Weg kennen, den Dämon zu schwächen, brauchen wir ein Gefäß, in das wir ihn binden können. Die Brennende Klinge hat antike elfische Ruinen im Süden von Desolace überrannt und nutzt sie jetzt als Beschwörungsplatz, um Dämonen nach Azeroth zu rufen.\n\nWenn Ihr ein Seelengefäß gefunden habt, trefft uns in Desolace. Dort werden wir das Ritual vollenden.", progress = "Mit dem Zweig der Schatten und dem Seelengefäß können wir das Ritual beginnen.", completion = "Ah, ja... ja! Das ist genau, was wir brauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[78916] = { id = 78916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herz der Leere", description = "Die Schreckensbestie Aku'mai wurde getötet. In den Eingeweiden ihres angeschwollenen Leichnams ist eine gewaltige schillernde Perle versteckt, die geradezu vor roher Leerenenergie strotzt.", sourceObjective = "Bringt die Blackfathom-Perle zu Dämmerungsbehüter Selgorm in Darnassus.", progress = "{name}, welche Neuigkeiten bringt Ihr aus Blackfathom?", completion = "Aku'mai, Dienerin der Alten Götter, ist tot. Eine Errungenschaft, wie sie nur wahre Helden vollbringen können.\n\nDieser Gegenstand könnte uns zu einem deutlich besseren Verständnis der Beschaffenheit der Leere und ihrer Auswirkungen auf unsere Welt verhelfen. Wir müssen ihn umgehend erforschen. Vielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[78917] = { id = 78917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herz der Leere", description = "Die Schreckensbestie Aku'mai wurde getötet. In den Eingeweiden ihres angeschwollenen Leichnams ist eine gewaltige schillernde Perle versteckt, die geradezu vor roher Leerenenergie strotzt.", sourceObjective = "Bringt die Blackfathom-Perle zu Bashana Runetotem in Thunder Bluff.", progress = "{name}, welche Neuigkeiten bringt Ihr aus Blackfathom?", completion = "Aku'mai, Dienerin der Alten Götter, ist tot. Ihr habt den Einwohnern Kalimdors mit dieser Tat einen enormen Dienst erwiesen.\n\nDie Perle könnte uns zu einem deutlich besseren Verständnis der Beschaffenheit der Leere und ihrer Auswirkungen auf unsere Welt verhelfen. Wir müssen sie umgehend erforschen. Geht mit der Erdenmutter, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[78920] = { id = 78920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baron Aquanis", description = "Der besiegte Wasserelementar hat eine seltsame Wasserkugel zurückgelassen. Ihr vermutet, dass das Objekt die Kreatur irgendwie mit Energie versorgte. In der Kugel schwappt eine faulig aussehende Wassergestalt herum. Die Kugel selbst zeigt sich unbeeindruckt von jeder äußerlichen Krafteinwirkung.\n\nWenn irgendwer aus diesem Gegenstand schlau wird, wäre das wohl Je'neu Sancrea vom Irdenen Ring. Er befindet sich beim Zoram'gar-Außenposten der Horde in Ashenvale.", sourceObjective = "Bringt die seltsame Wasserkugel zu Je'neu Sancrea beim Zoram'gar-Außenposten in Ashenvale.", progress = "Ach, hallo, {name}. Ich habe gerade in den Wellen der See gelesen, wie ich es immer tue. Was führt Euch in den Außenposten?", completion = "Das... Das ist ein wichtiger Fund, {name}.\n\nIhr habt dies von Baron Aquanis aus Blackfathom, sagt Ihr? Man hatte Baron Aquanis schon lange im Verdacht, eine verderbte Elementarkraft zu sein. Diese Kugel wird zeigen, was genau ihn verdorben hat. Es würde mich nicht im Geringsten überraschen, wenn es sich dabei um die Twilight-Hammer handelt. Aber unsere Studien werden auch aufzeigen, wie sie das getan haben.\n\nIhr habt das Richtige getan, indem Ihr dies zu mir brachtet. Bitte, nehmt dies zusammen mit den wärmsten Empfehlungen des Irdenen Rings.", sourceObjectiveStatus = "unverified-source-field" }
quests[78921] = { id = 78921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schurkerei in Blackfathom", description = "Die Kraft hat mich verlassen. Ich benötige Eure Hilfe!\n\nDiese Stätte war einst ein großer Tempel von Elune. Doch das Unglück führte zum Untergang, als die Verderbnis eines Alten Gottes unter der Erde emporwallte und den heiligen Mondbrunnen besudelte.\n\nAku'mai, die Dienerin der Alten Götter, erhob sich aus den Wassern.\n\nDie Kultisten der Twilight-Hammer haben sich mit den Naga verschworen, um diese Ländereien zu besetzen. Die Kultisten opfern unter Führung von Kelris Unschuldige für Aku'mai, um Macht zu erlangen.\n\nBitte, tötet Kelris und bringt Selgorm in Darnassus seinen Kopf, {name}.", sourceObjective = "Bringt den Kopf von Twilight-Lord Kelris zu Dämmerungsbehüter Selgorm in Darnassus.", progress = "Zeit ist ein kostbares Gut, {class}.\n\nMeine Rolle hier in Darnassus ist es, sicherzustellen, dass die Argentumdämmerung gedeiht und die bösen Mächte aus Kalimdor vertrieben werden.\n\nSagt rasch, was Euer Begehr ist, oder zieht von dannen.", completion = "Kelris entwischt uns schon seit geraumer Zeit.\n\nOffenbar ist Kelris stets dabei, wenn das Böse in dieser Region sein hässliches Haupt erhebt. Eine Zeit lang hielten wir ihn für tot oder vermisst.\n\nDoch dies scheint logisch zu sein. Als Ihr seine Herrschaft beendet habt, habt Ihr vielen Unschuldigen das Leben gerettet.\n\nBeim Licht! Es ist mehr als schändlich, jemanden den Dienern eines Alten Gottes zu opfern, um persönlich Kapital daraus zu schlagen!\n\nIhr habt eine große Tat vollbracht, {name}. Ich salutiere im Namen der Argentumdämmerung vor Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[78922] = { id = 78922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schurkerei in Blackfathom", description = "Die Kraft hat mich verlassen. Ich benötige Eure Hilfe!\n\nDiese Stätte war einst ein großer Tempel von Elune. Doch das Unglück führte zum Untergang, als die Verderbnis eines Alten Gottes unter der Erde emporwallte und den heiligen Mondbrunnen besudelte.\n\nAku'mai, die Dienerin der Alten Götter, erhob sich aus den Wassern.\n\nDie Kultisten der Twilight-Hammer haben sich mit den Naga verschworen, um diese Ländereien zu besetzen. Die Kultisten opfern unter Führung von Kelris Unschuldige für Aku'mai, um Macht zu erlangen.\n\nBitte, tötet Kelris und bringt Bashana in Thunder Bluff seinen Kopf, {name}.", sourceObjective = "Bringt den Kopf von Twilight-Lord Kelris zu Bashana Runetotem in Thunder Bluff.", progress = "Möge die Erdenmutter mit Euch sein, {name}.\n\nUnser Ziel sollte Friede auf der Erde sein und unter denen, die sie bewohnen. Sie hat große Pläne mit der Natur und wir alle müssen unsere Rolle in diesem Plan spielen.", completion = "Kelris hat sich der Argentumdämmerung eine ganze Weile entzogen.\n\nEine Zeit lang galt er sogar als tot oder vermisst.\n\nIndem Ihr seinem Regime ein Ende gemacht habt, habt Ihr die Leben vieler Unschuldiger gerettet, {name}.\n\nGelobt sei die Erdenmutter! Jemanden einem Diener eines Alten Gottes zu opfern, um persönlich davon zu profitieren, ist mehr als verachtenswert!\n\nHeute habt Ihr etwas Großes geleistet! Kelris war eine Kreatur des Bösen und trachtete danach, die Welt wieder in eine Zeit des Chaos zu stürzen, indem er einem der Alten Götter huldigte. Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[78923] = { id = 78923, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wissen in der Tiefe", description = "Wie Ihr vielleicht wisst, trage ich Lehren zusammen. Alte Lehren. Mächtige Lehren. Lehren, die Portale öffnen, und Lehren, die die Schlafenden erwecken können.\n\nEs kursieren Gerüchte um einen alten Teil einer Lehre, das \"Manuskript von Lorgalis\", das sich tief unten in der Blackfathom-Tiefe in Ashenvale befinden soll. Dieser Ort ist die ehemalige Heimat längst verstorbener Elfen. Elfen, die über großes Wissen verfügten, bevor ihre Stadt zerfiel.\n\nSucht in der Blackfathom-Tiefe nach dem Manuskript. Wenn Ihr das tut, werde ich Euch das nie vergessen. Auch nicht... nach dem Ende aller Tage.", sourceObjective = "Bringt das Manuskript von Lorgalis zu Gerrig Bonegrip in Ironforge.", progress = "Die Reise nach Ashenvale ist lang und Eure Aufgabe ist nicht leicht. Aber wenn Ihr mir das Manuskript bringt, {name}...dann werde ich Euch fürstlich belohnen.", completion = "Ihr habt das Manuskript gefunden! Was für ein Freudentag! Wir werden es nachdrucken und verteilen, und dann können auch meine Brüder und Schwestern endlich des alten Wissens von Lorgalis teilhaftig werden!\n\nIhr habt uns mehr geholfen, als Ihr ahnt, {name}. Ich hoffe jedoch, dass dieses Geschenk Euch zeigt, wie dankbar wir uns unseren Verbündeten erweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[78924] = { id = 78924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Thaelrid", description = "Heutzutage kursieren viele Gerüchte über die Vereinigung der Twilight-Hammer und Naga in der Blackfathom-Tiefe an den Küsten von Ashenvale.\n\nMeine Rolle hier bei der Argentumdämmerung besteht darin, so viele Informationen wie möglich zu sammeln, damit wir wissen, wann und wo Hilfe erforderlich ist.\n\nEs ist jetzt Wochen her, seit ich einen Späher losschickte, um die Aktivitäten in der Blackfathom-Tiefe auszuspähen. Argentumwache Thaelrid hat sich noch nicht zurückgemeldet.\n\nMeine anderen Späher sind mit dringenden Angelegenheiten beschäftigt.\n\nSucht und unterstützt Thaelrid für mich, {name}.", sourceObjective = "Sucht Argentumwache Thaelrid in der Blackfathom-Tiefe auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[78925] = { id = 78925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Twilight fallen", description = "Mit der Macht der uralten Rituale der chaotischen Alten Götter versuchen die Mitglieder der Twilight-Hammer, ihre dunklen Schutzherren zurückzuholen und Tod und Schrecken in der Welt zu verbreiten.\n\nWir glauben, dass die Twilight-Hammer sich mit den Naga verbündet haben und sich in der Blackfathom-Tiefe an den Küsten von Ashenvale zusammenrotten.\n\nWelch schändliche Pläne in den Tiefen des alten Tempels auch immer geschmiedet werden, wir müssen sie vereiteln.\n\nFührt Krieg gegen die Hammer und bringt Beweise Eurer Taten mit. Eure Bemühungen sollen reich belohnt werden.", sourceObjective = "Bringt 10 Twilight-Anhänger zu Argentumwache Manados in Darnassus.", progress = "Die Blackfathom-Tiefe war einst ein alter Tempel der Nachtelfen. Ehedem befand sich einer der mächtigsten Mondbrunnen darin. Wer weiß, welches Übel die Twilight-Hammer jetzt dort ausbrüten?\n\nHabt Ihr schon Fortschritte bei ihrer Vertreibung erzielt?", completion = "Ihr seid zweifellos von tapferem und edlem Geblüt, {name}. Die Argentumdämmerung dankt Euch für Euren Einsatz gegen das Böse.", sourceObjectiveStatus = "unverified-source-field" }
quests[78926] = { id = 78926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erforschung der Verderbnis", description = "Törichte Blutelfen spielen mit Dämonenmagie. Wurden sie nicht Zeugen, was mit den Naga und den Satyrn von Kalimdor geschehen ist?\n\nIch fürchte, die Blutelfen werden auf ähnliche Weise deformiert. Azeroth darf kein weiteres Volk abscheulicher Monster hervorbringen.\n\nIch möchte die Hirnstämme der Satyrn und Naga untersuchen, damit ich daraus folgern kann, welches Schicksal die Elfen erwartet. In der Blackfathom-Tiefe an der Küste Ashenvales werdet Ihr sowohl Satyrn als auch Naga finden.\n\nEs ist eine lange Reise, {name}.", sourceObjective = "Gershala Nightwhisper in Auberdine möchte 8 verderbte Hirnstämme.", progress = "Wenn ich genügend Proben habe, kann meine wahre Arbeit beginnen. Mit den verderbten Hirnstämmen der Satyrn und Naga der Blackfathom-Tiefe kann ich versuchen, einen Zusammenhang zwischen den Mutationen zu finden.\n\nMit diesem Wissen verhindern wir vielleicht, dass die Blutelfen noch deformierter und böser werden.", completion = "Ihr seid weit gereist und habt zweifellos großen Gefahren getrotzt.\n\nEure Taten waren selbstlos. Es dient ganz Azeroth, wenn Ihr mir bei meinen Forschungen helft. Ich danke Euch für alles, was Ihr getan habt, {name}.\n\nWenn Ihr mich nun entschuldigen wollt, ich habe viel Arbeit...", sourceObjectiveStatus = "unverified-source-field" }
quests[78927] = { id = 78927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treue zu den Alten Göttern", description = "Dieser Anhänger der Twilight-Hammer darf seinen Plan nicht in die Tat umsetzen. Die Twilight-Hammer verstehen die Geister der Natur nicht. Sie glauben an die Alten Götter - Kreaturen des Chaos und der Zerstörung, die vor langer Zeit besiegt wurden. Dieser Lorgus darf keinen Erfolg haben. Ihr müsst ihn aufhalten, {name}. Ich kann mich leider nicht selbst darum kümmern... ich bin zu schwach.\n\nGeht zur Blackfathom-Tiefe, findet ihn und tötet ihn. Kommt zu mir nach Zoram'gar zurück, wenn Ihr es geschafft habt.", sourceObjective = "Tötet Lorgus Jett in der Blackfathom-Tiefe und kehrt dann zu Je'neu Sancrea in Ashenvale zurück.", completion = "Sehr gut! Danke, {name}. Wir mögen zwar die Twilight-Hammer nicht vollständig aufgehalten haben, aber zumindest habt Ihr einen weiteren ihrer Pläne durchkreuzt, die Alten Götter wieder mächtig zu machen.\n\nWer weiß, welche Pläne sie sonst noch verfolgen mochten, aber wir können vorerst beruhigt sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[78994] = { id = 78994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine solide Grundlage", description = "Die Waffe neu zu schmieden, hat sich als Herausforderung herausgestellt, und es ist immer noch unklar, wie das Ritual scheitern konnte, aber ich glaube, wir haben eine alternative Lösung gefunden.\n\nUm anzufangen, brauchen wir eine solide Basis, einen Zweig der Schatten.\n\nDiese Bäume sind bösartige Gewächse, die aus dem Smaragdgrünen Alptraum in unsere Welt herübersickern. Es heißt, sie schwächen den Willen derer in ihrer Umgebung. Diese magische Eigenschaft wird die Grundlage für den Bau dieser Waffe sein.\n\nDieser Trank wird Euch bei Eurer Suche helfen. Er wird Euch vor den Dienern der Smaragddrachen verbergen.", sourceObjective = "Die Smaragddrachen schützen mehrere Portale in den Smaragdgrünen Traum in ganz Azeroth. An einem dieser Orte ist sicher zu finden, was wir brauchen.\n\nWenn Ihr einen Zweig der Schatten gefunden habt, kommt so schnell wie möglich hierher zurück.", progress = "Niemand hat behauptet, es wäre ein einfaches Unterfangen, aber das sind die wenigsten Dinge, die es wert sind.", completion = "Ah, ja, Ihr habt ihn gefunden! Euer Verstand scheint auch noch intakt zu sein. So weit, so gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[79007] = { id = 79007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "...und diese Notiz, die Ihr gefunden habt.", description = "Ihr stolpert über die noch frischen Überreste eines Feuers, dessen schwaches Leuchten der Glut weiter nachlässt.\nInmitten der verstreuten Vorräte entdeckt Ihr eine fast verbrannte Notiz.\n\"Nicht alles, was brennt, ist verloren. Findet das Zwillingsland, findet den Ort.\"", sourceObjective = "Die verkohlten Überreste der Notiz dienen Euch als einziger Wegweiser.", completion = "Als Ihr über die Überreste einer weiteren verkohlten Leiche stolpert, fällt Euer Blick auf eine Notiz, die an einer Holzplanke befestigt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[79008] = { id = 79008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "...und diese Notiz, die Ihr gefunden habt.", description = "Ihr stolpert über die noch frischen Überreste eines Feuers, dessen schwaches Leuchten der Glut weiter nachlässt.\nInmitten der verstreuten Vorräte entdeckt Ihr eine fast verbrannte Notiz.\n\"Nicht alles, was brennt, ist verloren. Findet das Zwillingsland, findet den Ort.\"", sourceObjective = "Die verkohlten Überreste der Notiz dienen Euch als einziger Wegweiser.", completion = "Als Ihr über die Überreste einer weiteren verkohlten Leiche stolpert, fällt Euer Blick auf eine Notiz, die an einer Holzplanke befestigt ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[79077] = { id = 79077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemeinsamer Glaube", description = "Das Licht ruft uns zu Gerechtigkeit und Schutz auf, aber auch zu Barmherzigkeit. Unsere Verbündeten sind fremd in diesen Landen und wir haben die Pflicht, ihnen unsere Gepflogenheiten näherzubringen.\nDieser Nachtelf sucht das Licht, hat jedoch Probleme bei der Meditation. Würde Ihr ihm helfen?", sourceObjective = "Meditiert über das Licht und betet dann mit dem knieenden Elfen, um Eure Meditation zu teilen.", completion = "Das Licht bringt seine Segen durch Euch zum Vorschein, {name}. Ehrt das, indem Ihr Eure Weisheit mit allen Bittstellern teilt, die Euch auf Euren Reisen begegnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79078] = { id = 79078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemeinsamer Glaube", description = "Dieser Mensch greift nach Elunes Licht, doch seine Sicht ist getrübt. Könntet Ihr ihm helfen?", sourceObjective = "Meditiert über Elune und betet dann mit dem knieenden Menschen, um Eure Meditation zu teilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[79079] = { id = 79079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemeinsamer Glaube", description = "Dieser arme Priester der Verlassenen scheint keinen Loa zu finden, der mit ihm handeln möchte. Vielleicht könntet Ihr ihm stattdessen einen Segen geben?", sourceObjective = "Meditiert über die Loa und betet dann mit dem knieenden Verlassenen, um Eure Meditation zu teilen.", completion = "Die Untoten sind bei den Loa nicht sonderlich beliebt, aber es ist gut von Euch, diesem auszuhelfen. Versucht, etwas Mitgefühl zu zeigen, wenn Ihr unterwegs mehr von ihnen trefft, okay?", sourceObjectiveStatus = "unverified-source-field" }
quests[79080] = { id = 79080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemeinsamer Glaube", description = "Dieser Troll versucht, über den Tod zu reflektieren, allerdings fehlt es ihm an einer gewissen... Vertrautheit mit der Thematik. Helft ihm bitte dabei, es besser zu verstehen.", sourceObjective = "Meditiert über den Untod und betet dann mit dem knieenden Troll, um Eure Meditation zu teilen.", completion = "Meiner Erfahrung nach, ist unser Volk bestenfalls eine Kuriosität für den Rest der Horde. Dennoch, unser Wissen zu Teilen, ist eine einfache Methode, uns ihr Vertrauen zu verdienen. Behaltet das auf Euren Reisen im Kopf.", sourceObjectiveStatus = "unverified-source-field" }
quests[79090] = { id = 79090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eindringlinge abwehren", description = "Einige Mitglieder der Warsongvorhut wurden besiegt, doch die Schlacht geht weiter...", sourceObjective = "Bringt das Abzeichen der Warsongvorhut zur Mondpriesterin Felore Mondschein in der Mondbrunnenbasis in Ashenvale.", progress = "{name}, welche Neuigkeiten bringt Ihr von der Front?", completion = "Die Eindringlinge der Horde beschmutzen nach wie vor unsere Lande und stehlen von unserer heiligen Wildnis. Werft sie weiterhin hinaus!\n\nDiese heilige Kampfeshymne kann Euch inspirieren, sie mit noch größerer Entschlossenheit zu bekämpfen. Vielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[79091] = { id = 79091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erzmagier Antonidas: Die ungekürzte Autobiografie", progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Vielen Dank, {name}. Ihr sagtet, das sei aus der Bibliothek in Ironforge? ...Ich bin sicher, sie werden es nicht vermissen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte." }
quests[79092] = { id = 79092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forschungsaufzeichnungen von Erzmagier Theocritus", progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, {name}. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte." }
quests[79093] = { id = 79093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rumi von Gnomeregan: Die gesammelten Werke", progress = "Habt Ihr einen Neuzugang für unsere Sammlung mitgebracht?", completion = "Ich danke Euch, {name}. Unser Wissen erweitert sich durch Eure Bemühungen.\n\nFalls Ihr noch mehr magische Werke findet, die der Bibliothek zugutekommen könnten, so bringt sie mir bitte." }
